import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";

/**
 * Test successful guest registration for creating a new member account.
 *
 * This test validates that a guest user can successfully register with valid
 * credentials (username, email, password) and receive JWT authentication tokens
 * for immediate access.
 *
 * Test workflow:
 *
 * 1. Generate valid registration data with proper constraints
 * 2. Submit registration request to the API
 * 3. Validate the complete response structure with typia.assert
 */
export async function test_api_guest_registration_new_member_account(
  connection: api.IConnection,
) {
  // Generate valid registration data using typia.random with proper tags
  const registrationData = {
    username: typia.random<
      string &
        tags.MinLength<3> &
        tags.MaxLength<30> &
        tags.Pattern<"^[a-zA-Z0-9_-]+$">
    >(),
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardGuest.IRegistration;

  // Submit registration request
  const response: IDiscussionBoardGuest.IAuthorized =
    await api.functional.auth.guest.join(connection, {
      body: registrationData,
    });

  // Validate complete response structure - this validates EVERYTHING
  typia.assert(response);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";

/**
 * Test the token refresh mechanism for maintaining seamless guest sessions.
 *
 * This test validates that users with a valid refresh token can obtain a new
 * access token when their current access token expires, ensuring continuous
 * authenticated sessions during extended browsing without repeatedly entering
 * credentials.
 *
 * Test workflow:
 *
 * 1. Register a new guest member account to obtain initial tokens
 * 2. Use the refresh token to request a new access token
 * 3. Verify the new token response contains valid access and refresh tokens
 * 4. Validate all session metadata is properly returned
 * 5. Test error handling with invalid refresh tokens
 */
export async function test_api_guest_token_refresh_seamless_session(
  connection: api.IConnection,
) {
  // Step 1: Register a new guest member to obtain initial tokens
  const registrationBody = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    password: "SecureP@ss123",
    ip: undefined,
    href: "https://discussion.example.com/register",
    referrer: "https://discussion.example.com/home",
  } satisfies IDiscussionBoardGuest.IRegistration;

  const initialGuest: IDiscussionBoardGuest.IAuthorized =
    await api.functional.auth.guest.join(connection, {
      body: registrationBody,
    });
  typia.assert(initialGuest);

  // Step 2: Use refresh token to obtain new access token
  const refreshBody = {
    refresh_token: initialGuest.token.refresh,
  } satisfies IDiscussionBoardGuest.IRefresh;

  const refreshedGuest: IDiscussionBoardGuest.IAuthorized =
    await api.functional.auth.guest.refresh(connection, {
      body: refreshBody,
    });
  typia.assert(refreshedGuest);

  // Step 3: Validate business logic - session identity persistence
  TestValidator.equals(
    "guest ID remains the same after refresh",
    refreshedGuest.id,
    initialGuest.id,
  );
  TestValidator.equals(
    "session token remains the same after refresh",
    refreshedGuest.session_token,
    initialGuest.session_token,
  );

  // Step 4: Test error handling with invalid refresh token
  await TestValidator.error("invalid refresh token should fail", async () => {
    await api.functional.auth.guest.refresh(connection, {
      body: {
        refresh_token: "invalid_token_" + RandomGenerator.alphaNumeric(20),
      } satisfies IDiscussionBoardGuest.IRefresh,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAuth";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Test successful member login authentication workflow.
 *
 * This test validates the complete authentication flow for a member:
 *
 * 1. Create a new member account through registration with valid credentials
 * 2. Authenticate using the login endpoint with valid credentials
 * 3. Validate login response contains proper JWT tokens and user information
 * 4. Verify authenticated member information matches registered account
 * 5. Confirm session is successfully established
 */
export async function test_api_member_login_authentication_success(
  connection: api.IConnection,
) {
  // Step 1: Create a new member account through registration
  const registrationEmail = typia.random<string & tags.Format<"email">>();
  const registrationPassword = "SecurePass123!";
  const registrationUsername = RandomGenerator.alphaNumeric(12);

  const registrationData = {
    username: registrationUsername,
    email: registrationEmail,
    password: registrationPassword,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMember.IJoin;

  const registeredMember: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: registrationData,
    });
  typia.assert(registeredMember);

  // Step 2: Authenticate using the login endpoint with registered credentials
  const loginData = {
    username_or_email: registrationUsername,
    password: registrationPassword,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardAuth.ILogin;

  const loginResult: IDiscussionBoardAuth.ILoginResult =
    await api.functional.discussionBoard.auth.login(connection, {
      body: loginData,
    });
  typia.assert(loginResult);

  // Step 3: Verify authenticated member information matches registered account
  TestValidator.equals(
    "user ID matches registration",
    loginResult.id,
    registeredMember.id,
  );
  TestValidator.equals(
    "username matches registration",
    loginResult.username,
    registrationUsername,
  );
  TestValidator.equals(
    "email matches registration",
    loginResult.email,
    registrationEmail,
  );
  TestValidator.equals(
    "email_verified status matches",
    loginResult.email_verified,
    registeredMember.email_verified,
  );

  // Step 4: Verify role designation
  TestValidator.equals("role should be member", loginResult.role, "member");
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAuth";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Test complete member logout workflow including session termination and token
 * invalidation.
 *
 * This test validates the entire logout process for a discussion board member:
 *
 * 1. Create a new member account through registration
 * 2. Authenticate the member to establish an active session with valid tokens
 * 3. Perform logout operation to terminate the current session
 * 4. Verify that the logout successfully invalidates tokens and terminates the
 *    session
 *
 * The logout operation should mark the session as expired in the database by
 * setting the expired_at timestamp, preventing the refresh token from being
 * reused to obtain new access tokens. This ensures proper session management
 * and security.
 */
export async function test_api_member_logout_session_termination(
  connection: api.IConnection,
) {
  // Step 1: Create a new member account
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberUsername = typia.random<
    string &
      tags.MinLength<3> &
      tags.MaxLength<30> &
      tags.Pattern<"^[a-zA-Z0-9_-]+$">
  >();
  const memberPassword = typia.random<string & tags.MinLength<8>>();

  const joinData = {
    username: memberUsername,
    email: memberEmail,
    password: memberPassword,
    ip: "192.168.1.100",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMember.IJoin;

  const registeredMember: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: joinData,
    });
  typia.assert(registeredMember);

  TestValidator.equals(
    "registered member email matches",
    registeredMember.email,
    memberEmail,
  );
  TestValidator.equals(
    "registered member username matches",
    registeredMember.username,
    memberUsername,
  );

  // Step 2: Authenticate member to establish active session
  const loginData = {
    username_or_email: memberEmail,
    password: memberPassword,
    ip: "192.168.1.100",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMember.ILogin;

  const authenticatedMember: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.login(connection, {
      body: loginData,
    });
  typia.assert(authenticatedMember);

  TestValidator.equals(
    "authenticated member ID matches registered member",
    authenticatedMember.id,
    registeredMember.id,
  );

  // Step 3: Perform logout operation
  const logoutResult: IDiscussionBoardAuth.ILogoutResult =
    await api.functional.discussionBoard.member.auth.logout(connection);
  typia.assert(logoutResult);

  // Step 4: Validate logout success
  TestValidator.equals(
    "logout operation succeeded",
    logoutResult.success,
    true,
  );

  TestValidator.predicate(
    "logout message is provided",
    logoutResult.message.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Test the complete member token refresh workflow using a valid refresh token.
 *
 * This test validates the seamless session continuation mechanism that allows
 * members to maintain authenticated sessions without re-entering credentials
 * when their access token expires. The test creates a new member account,
 * obtains initial tokens through join, then uses the refresh token to get a new
 * access token.
 *
 * Steps:
 *
 * 1. Create a new member account through join operation
 * 2. Extract refresh token from the join response
 * 3. Call the token refresh endpoint with the refresh token
 * 4. Validate new access token and expiration metadata
 * 5. Verify member information is included for client state sync
 */
export async function test_api_member_token_refresh_with_valid_refresh_token(
  connection: api.IConnection,
) {
  // Step 1: Create a new member account to get initial tokens
  const joinData = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.MinLength<8>>(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMember.IJoin;

  const joinedMember: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: joinData,
    });
  typia.assert(joinedMember);

  // Step 2: Extract the refresh token from join response
  const refreshToken: string = joinedMember.token.refresh;
  TestValidator.predicate(
    "refresh token should exist",
    refreshToken.length > 0,
  );

  // Step 3: Use the refresh token to obtain new access token
  const refreshedMember: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.refresh(connection, {
      body: {
        refreshToken: refreshToken,
      } satisfies IDiscussionBoardMember.IRefresh,
    });
  typia.assert(refreshedMember);

  // Step 4: Validate the new access token exists and has proper structure
  TestValidator.predicate(
    "new access token should exist",
    refreshedMember.token.access.length > 0,
  );
  TestValidator.predicate(
    "new refresh token should exist",
    refreshedMember.token.refresh.length > 0,
  );

  // Step 5: Validate token expiration metadata exists
  TestValidator.predicate(
    "access token expiration should be set",
    refreshedMember.token.expired_at.length > 0,
  );
  TestValidator.predicate(
    "refresh token expiration should be set",
    refreshedMember.token.refreshable_until.length > 0,
  );

  // Step 6: Verify member information is included in response
  TestValidator.equals(
    "member ID should match",
    refreshedMember.id,
    joinedMember.id,
  );
  TestValidator.equals(
    "member username should match",
    refreshedMember.username,
    joinedMember.username,
  );
  TestValidator.equals(
    "member email should match",
    refreshedMember.email,
    joinedMember.email,
  );
}

