    title: "Economic Policy Analysis and Future Trends",
    body:
      RandomGenerator.content({ paragraphs: 3 }) +
      " economy economic monetary policy",
    summary: "Analysis of current economic trends",
    category_ids: [category.id],
    tag_ids: [],
    image_ids: [],
    document_ids: [],
