import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleDocument } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleDocument";
import type { IDiscussionBoardArticleImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleImage";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardComment";

/**
 * Test pagination and sorting capabilities when retrieving replies to a
 * comment.
 *
 * This test validates that the comment replies retrieval operation properly
 * handles large sets of replies with configurable page sizes and multiple
 * sorting options.
 *
 * Test process:
 *
 * 1. Create moderator account and category
 * 2. Create member account and article
 * 3. Create a parent comment on the article
 * 4. Create multiple reply comments (20 replies) to test pagination
 * 5. Test pagination with different page sizes (5, 10, 20)
 * 6. Validate pagination metadata (total count, pages, current page)
 * 7. Test sorting by creation date (ascending and descending)
 * 8. Test sorting by update date
 * 9. Verify correct parent comment association
 */
export async function test_api_comment_replies_pagination_and_sorting(
  connection: api.IConnection,
) {
  // Create moderator account
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Create category (moderator is now authenticated)
  const category =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: {
          name: RandomGenerator.name(2),
          description: RandomGenerator.paragraph({ sentences: 5 }),
        } satisfies IDiscussionBoardCategory.ICreate,
      },
    );
  typia.assert(category);

  // Create member account
  const member = await api.functional.auth.member.join(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardMember.IJoin,
  });
  typia.assert(member);

  // Create article (member is now authenticated)
  const article = await api.functional.discussionBoard.member.articles.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({ sentences: 3 }),
        body: RandomGenerator.content({ paragraphs: 5 }),
        category_ids: [category.id],
      } satisfies IDiscussionBoardArticle.ICreate,
    },
  );
  typia.assert(article);

  // Create parent comment (top-level comment on the article)
  const parentComment =
    await api.functional.discussionBoard.articles.comments.create(connection, {
      articleId: article.id,
      body: {
        discussion_board_article_id: article.id,
        discussion_board_parent_comment_id: null,
        content: RandomGenerator.paragraph({ sentences: 5 }),
      } satisfies IDiscussionBoardComment.ICreate,
    });
  typia.assert(parentComment);

  // Create 20 reply comments for pagination testing (all as member)
  const replyIds: string[] = [];

  for (let i = 0; i < 20; i++) {
    const reply = await api.functional.discussionBoard.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: {
          discussion_board_article_id: article.id,
          discussion_board_parent_comment_id: parentComment.id,
          content: RandomGenerator.paragraph({ sentences: 3 }),
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
    typia.assert(reply);
    replyIds.push(reply.id);
  }

  // Test pagination with page size 5
  const page1Size5 =
    await api.functional.discussionBoard.articles.comments.replies.index(
      connection,
      {
        articleId: article.id,
        commentId: parentComment.id,
        body: {
          page: 1,
          limit: 5,
          sort_by: "created_at",
          sort_order: "desc",
        } satisfies IDiscussionBoardComment.IRequest,
      },
    );
  typia.assert(page1Size5);

  TestValidator.equals(
    "page 1 size 5 should have 5 items",
    page1Size5.data.length,
    5,
  );
  TestValidator.equals(
    "total records should be 20",
    page1Size5.pagination.records,
    20,
  );
  TestValidator.equals(
    "total pages should be 4 for size 5",
    page1Size5.pagination.pages,
    4,
  );
  TestValidator.equals(
    "current page should be 1",
    page1Size5.pagination.current,
    1,
  );

  // Test page 2 with size 5
  const page2Size5 =
    await api.functional.discussionBoard.articles.comments.replies.index(
      connection,
      {
        articleId: article.id,
        commentId: parentComment.id,
        body: {
          page: 2,
          limit: 5,
          sort_by: "created_at",
          sort_order: "desc",
        } satisfies IDiscussionBoardComment.IRequest,
      },
    );
  typia.assert(page2Size5);

  TestValidator.equals(
    "page 2 size 5 should have 5 items",
    page2Size5.data.length,
    5,
  );
  TestValidator.equals(
    "page 2 current page should be 2",
    page2Size5.pagination.current,
    2,
  );

  // Test pagination with page size 10
  const page1Size10 =
    await api.functional.discussionBoard.articles.comments.replies.index(
      connection,
      {
        articleId: article.id,
        commentId: parentComment.id,
        body: {
          page: 1,
          limit: 10,
          sort_by: "created_at",
          sort_order: "desc",
        } satisfies IDiscussionBoardComment.IRequest,
      },
    );
  typia.assert(page1Size10);

  TestValidator.equals(
    "page 1 size 10 should have 10 items",
    page1Size10.data.length,
    10,
  );
  TestValidator.equals(
    "total pages should be 2 for size 10",
    page1Size10.pagination.pages,
    2,
  );

  // Test sorting by creation date descending (newest first)
  const sortedNewest =
    await api.functional.discussionBoard.articles.comments.replies.index(
      connection,
      {
        articleId: article.id,
        commentId: parentComment.id,
        body: {
          page: 1,
          limit: 20,
          sort_by: "created_at",
          sort_order: "desc",
        } satisfies IDiscussionBoardComment.IRequest,
      },
    );
  typia.assert(sortedNewest);

  TestValidator.equals(
    "sorted newest should return all 20 items",
    sortedNewest.data.length,
    20,
  );

  // Verify newest first ordering
  for (let i = 0; i < sortedNewest.data.length - 1; i++) {
    const current = new Date(sortedNewest.data[i].created_at).getTime();
    const next = new Date(sortedNewest.data[i + 1].created_at).getTime();
    TestValidator.predicate(
      "newest first: current should be >= next",
      current >= next,
    );
  }

  // Test sorting by creation date ascending (oldest first)
  const sortedOldest =
    await api.functional.discussionBoard.articles.comments.replies.index(
      connection,
      {
        articleId: article.id,
        commentId: parentComment.id,
        body: {
          page: 1,
          limit: 20,
          sort_by: "created_at",
          sort_order: "asc",
        } satisfies IDiscussionBoardComment.IRequest,
      },
    );
  typia.assert(sortedOldest);

  TestValidator.equals(
    "sorted oldest should return all 20 items",
    sortedOldest.data.length,
    20,
  );

  // Verify oldest first ordering
  for (let i = 0; i < sortedOldest.data.length - 1; i++) {
    const current = new Date(sortedOldest.data[i].created_at).getTime();
    const next = new Date(sortedOldest.data[i + 1].created_at).getTime();
    TestValidator.predicate(
      "oldest first: current should be <= next",
      current <= next,
    );
  }

  // Test sorting by updated_at
  const sortedByUpdate =
    await api.functional.discussionBoard.articles.comments.replies.index(
      connection,
      {
        articleId: article.id,
        commentId: parentComment.id,
        body: {
          page: 1,
          limit: 20,
          sort_by: "updated_at",
          sort_order: "desc",
        } satisfies IDiscussionBoardComment.IRequest,
      },
    );
  typia.assert(sortedByUpdate);

  TestValidator.equals(
    "sorted by update should return all 20 items",
    sortedByUpdate.data.length,
    20,
  );

  // Verify pagination metadata consistency
  TestValidator.equals(
    "all requests should show same total records",
    page1Size5.pagination.records,
    20,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleDocument } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleDocument";
import type { IDiscussionBoardArticleImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleImage";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";

/**
 * Test that a member can successfully check the status of a content report they
 * previously submitted.
 *
 * This test validates the transparency workflow where members can track their
 * submitted reports. The test follows these steps:
 *
 * 1. Create moderator account for category creation
 * 2. Create and authenticate as a member account
 * 3. Create a category for article organization
 * 4. Create an article as the target content
 * 5. Submit a content report on the article
 * 6. Retrieve the report details to check status and resolution
 *
 * Validation points:
 *
 * - Member can access reports they created themselves
 * - Report status is visible (pending, under review, resolved, or dismissed)
 * - Report includes the original reason category and detailed explanation
 *   submitted
 * - Timestamps show when report was created
 * - If resolved, resolution notes from moderators are visible
 */
export async function test_api_member_report_status_check(
  connection: api.IConnection,
) {
  // Step 1: Create moderator account for category creation
  const moderatorData = {
    username: RandomGenerator.alphaNumeric(10),
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.MinLength<8>>(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardModerator.ICreate;

  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: moderatorData,
    });
  typia.assert(moderator);

  // Step 2: Create and authenticate as a member account
  const memberData = {
    username: RandomGenerator.alphaNumeric(10),
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.MinLength<8>>(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMember.IJoin;

  const member: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: memberData,
    });
  typia.assert(member);

  // Step 3: Create a category for article organization
  const categoryData = {
    name: RandomGenerator.name(2),
    description: RandomGenerator.paragraph({ sentences: 5 }),
  } satisfies IDiscussionBoardCategory.ICreate;

  const category: IDiscussionBoardCategory =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: categoryData,
      },
    );
  typia.assert(category);

  // Step 4: Create an article as the target content
  const articleData = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 3 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    category_ids: [category.id],
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: articleData,
    });
  typia.assert(article);

  // Step 5: Submit a content report on the article
  const reportReasons = [
    "spam",
    "harassment",
    "hate_speech",
    "misinformation",
    "off_topic",
    "inappropriate_language",
    "personal_info",
    "other",
  ] as const;
  const selectedReason = RandomGenerator.pick(reportReasons);

  const reportData = {
    reported_article_id: article.id,
    reported_comment_id: null,
    report_reason: selectedReason,
    report_details: RandomGenerator.paragraph({ sentences: 3 }),
  } satisfies IDiscussionBoardReport.ICreate;

  const submittedReport: IDiscussionBoardReport =
    await api.functional.discussionBoard.member.reports.create(connection, {
      body: reportData,
    });
  typia.assert(submittedReport);

  // Step 6: Retrieve the report details to check status and resolution
  const retrievedReport: IDiscussionBoardReport =
    await api.functional.discussionBoard.reports.at(connection, {
      reportId: submittedReport.id,
    });
  typia.assert(retrievedReport);

  // Validate that member can access their own report
  TestValidator.equals(
    "report ID matches",
    retrievedReport.id,
    submittedReport.id,
  );

  // Validate report status is visible and accurate
  TestValidator.equals(
    "report status is pending",
    retrievedReport.status,
    "pending",
  );

  // Validate report includes original reason category
  TestValidator.equals(
    "report reason matches",
    retrievedReport.report_reason,
    selectedReason,
  );

  // Validate report includes detailed explanation
  TestValidator.equals(
    "report details match",
    retrievedReport.report_details,
    reportData.report_details,
  );

  // Validate timestamps are present
  TestValidator.predicate(
    "created_at timestamp exists",
    retrievedReport.created_at !== null &&
      retrievedReport.created_at !== undefined,
  );

  // Validate reporter information is accessible
  TestValidator.equals(
    "reporter ID matches member",
    retrievedReport.reporter.id,
    member.id,
  );

  // Validate reported article reference is included
  TestValidator.predicate(
    "reported article exists",
    retrievedReport.reportedArticle !== null,
  );
  if (retrievedReport.reportedArticle) {
    TestValidator.equals(
      "reported article ID matches",
      retrievedReport.reportedArticle.id,
      article.id,
    );
  }
}

