  // Step 4: Create an article to host comments
  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: {
        title: RandomGenerator.paragraph({ sentences: 2 }),
        body: RandomGenerator.content({ paragraphs: 3 }),
        summary: RandomGenerator.paragraph({ sentences: 1 }),
        category_ids: [category.id],
      } satisfies IDiscussionBoardArticle.ICreate,
    });
  typia.assert(article);

  // Step 5: Post a comment on the article
  const comment: IDiscussionBoardComment =
    await api.functional.discussionBoard.member.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: {
          discussion_board_article_id: article.id,
          content: RandomGenerator.paragraph({ sentences: 4 }),
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(comment);

  // Step 6: Submit a content report flagging the comment for violations
  const reportReasons = [
    "spam",
    "harassment",
    "hate_speech",
    "misinformation",
    "off_topic",
    "inappropriate_language",
    "personal_info",
    "other",
  ] as const;
  const selectedReason = RandomGenerator.pick(reportReasons);

  const createdReport: IDiscussionBoardReport =
    await api.functional.discussionBoard.member.reports.create(connection, {
      body: {
        reported_article_id: null,
        reported_comment_id: comment.id,
        report_reason: selectedReason,
        report_details:
          selectedReason === "other"
            ? RandomGenerator.paragraph({ sentences: 2 })
            : RandomGenerator.paragraph({ sentences: 1 }),
      } satisfies IDiscussionBoardReport.ICreate,
    });
  typia.assert(createdReport);

  // Step 7: Retrieve the report to verify comment-specific reporting works correctly
  const retrievedReport: IDiscussionBoardReport =
    await api.functional.discussionBoard.reports.at(connection, {
      reportId: createdReport.id,
    });
  typia.assert(retrievedReport);

  // Validate that report correctly references the comment as the target
  TestValidator.equals(
    "report should reference the comment ID",
    retrievedReport.reported_comment_id,
    comment.id,
  );

  // Validate that report does NOT reference an article
  TestValidator.equals(
    "report should not reference an article",
    retrievedReport.reported_article_id,
    null,
  );

  // Validate report reason is properly stored
  TestValidator.equals(
    "report reason should match submitted reason",
    retrievedReport.report_reason,
    selectedReason,
  );

  // Validate reporter information matches the member
  TestValidator.equals(
    "reporter should be the authenticated member",
    retrievedReport.reporter.id,
    member.id,
  );

  // Validate reported comment summary is included
  typia.assertGuard(retrievedReport.reportedComment!);
  TestValidator.equals(
    "reported comment should reference the correct comment",
    retrievedReport.reportedComment.id,
    comment.id,
  );

  // Validate report status is pending for new reports
  TestValidator.equals(
    "report status should be pending",
    retrievedReport.status,
    "pending",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleDocument } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleDocument";
import type { IDiscussionBoardArticleImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleImage";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticleImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticleImage";

/**
 * Test public retrieval and filtering of article image attachments without
 * authentication.
 *
 * This test validates that guest users can retrieve and filter article images
 * through the public API endpoint. It ensures that filtering works correctly
 * for various image properties including MIME type, dimensions, file size, and
 * upload date. The test also verifies pagination functionality and metadata
 * completeness.
 *
 * Workflow:
 *
 * 1. Create a member account for article authorship
 * 2. Create a moderator account for category creation
 * 3. Create a category (required for article creation)
 * 4. Create an article as the authenticated member
 * 5. Upload multiple images with different properties (varying MIME types,
 *    dimensions, sizes)
 * 6. Create an unauthenticated connection to simulate guest access
 * 7. Retrieve images with various filters (MIME type, size ranges, dimensions)
 * 8. Validate filtering results match expected criteria
 * 9. Test pagination with different page sizes
 * 10. Verify response metadata is complete and accurate
 */
export async function test_api_article_images_public_retrieval_with_filtering(
  connection: api.IConnection,
) {
  // Step 1: Create member account for article authorship
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.auth.member.join(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(12),
      email: memberEmail,
      password: typia.random<string & tags.MinLength<8>>(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardMember.IJoin,
  });
  typia.assert(member);

  // Step 2: Create moderator account for category creation
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(12),
      email: moderatorEmail,
      password: typia.random<string & tags.MinLength<8>>(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 3: Create category as moderator
  const category =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: {
          name: RandomGenerator.name(2),
          description: RandomGenerator.paragraph({ sentences: 3 }),
        } satisfies IDiscussionBoardCategory.ICreate,
      },
    );
  typia.assert(category);

  // Step 4: Switch back to member authentication to create article
  connection.headers = connection.headers ?? {};
  connection.headers.Authorization = member.token.access;

  const article = await api.functional.discussionBoard.member.articles.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({ sentences: 2 }),
        body: RandomGenerator.content({ paragraphs: 3 }),
        category_ids: [category.id],
      } satisfies IDiscussionBoardArticle.ICreate,
    },
  );
  typia.assert(article);

  // Step 5: Upload multiple images with different properties
  const mimeTypes = [
    "image/jpeg",
    "image/png",
    "image/gif",
    "image/webp",
  ] as const;
  const uploadedImages: IDiscussionBoardArticleImage[] = [];

  for (let i = 0; i < 8; i++) {
    const width = typia.random<
      number & tags.Type<"int32"> & tags.Minimum<50> & tags.Maximum<8000>
    >();
    const height = typia.random<
      number & tags.Type<"int32"> & tags.Minimum<50> & tags.Maximum<8000>
    >();
    const sizeBytes = typia.random<
      number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<5242880>
    >();
    const mimeType = RandomGenerator.pick(mimeTypes);

    const image =
      await api.functional.discussionBoard.member.articles.images.create(
        connection,
        {
          articleId: article.id,
          body: {
            url: typia.random<string & tags.Format<"uri">>(),
            original_name: `test_image_${i}.${mimeType.split("/")[1]}`,
            mime_type: mimeType,
            size_bytes: sizeBytes,
            width: width,
            height: height,
          } satisfies IDiscussionBoardArticleImage.ICreate,
        },
      );
    typia.assert(image);
    uploadedImages.push(image);
  }

  // Step 6: Create unauthenticated connection for guest access
  const guestConnection: api.IConnection = { ...connection, headers: {} };

  // Step 7 & 8: Test filtering by MIME type
  const jpegFilter = await api.functional.discussionBoard.articles.images.index(
    guestConnection,
    {
      articleId: article.id,
      body: {
        mime_type: "image/jpeg",
        page: 1,
        limit: 20,
      } satisfies IDiscussionBoardArticleImage.IRequest,
    },
  );
  typia.assert(jpegFilter);

  const expectedJpegImages = uploadedImages.filter(
    (img) => img.mime_type === "image/jpeg",
  );
  TestValidator.equals(
    "MIME type filtering returns only JPEG images",
    jpegFilter.data.length,
    expectedJpegImages.length,
  );

  // Test filtering by size range
  const minSize = 100000;
  const maxSize = 3000000;
  const sizeRangeFilter =
    await api.functional.discussionBoard.articles.images.index(
      guestConnection,
      {
        articleId: article.id,
        body: {
          min_size_bytes: minSize,
          max_size_bytes: maxSize,
          page: 1,
          limit: 20,
        } satisfies IDiscussionBoardArticleImage.IRequest,
      },
    );
  typia.assert(sizeRangeFilter);

  const expectedSizeImages = uploadedImages.filter(
    (img) => img.size_bytes >= minSize && img.size_bytes <= maxSize,
  );
  TestValidator.equals(
    "size range filtering returns correct images",
    sizeRangeFilter.data.length,
    expectedSizeImages.length,
  );

  // Test filtering by dimensions
  const minWidth = 200;
  const maxHeight = 5000;
  const dimensionFilter =
    await api.functional.discussionBoard.articles.images.index(
      guestConnection,
      {
        articleId: article.id,
        body: {
          min_width: minWidth,
          max_height: maxHeight,
          page: 1,
          limit: 20,
        } satisfies IDiscussionBoardArticleImage.IRequest,
      },
    );
  typia.assert(dimensionFilter);

  const expectedDimensionImages = uploadedImages.filter(
    (img) => img.width >= minWidth && img.height <= maxHeight,
  );
  TestValidator.equals(
    "dimension filtering returns correct images",
    dimensionFilter.data.length,
    expectedDimensionImages.length,
  );

  // Step 9: Test pagination
  const page1 = await api.functional.discussionBoard.articles.images.index(
    guestConnection,
    {
      articleId: article.id,
      body: {
        page: 1,
        limit: 3,
      } satisfies IDiscussionBoardArticleImage.IRequest,
    },
  );
  typia.assert(page1);

  TestValidator.predicate(
    "first page contains correct number of items",
    page1.data.length <= 3,
  );
  TestValidator.equals(
    "pagination current page is 1",
    page1.pagination.current,
    1,
  );

  const page2 = await api.functional.discussionBoard.articles.images.index(
    guestConnection,
    {
      articleId: article.id,
      body: {
        page: 2,
        limit: 3,
      } satisfies IDiscussionBoardArticleImage.IRequest,
    },
  );
  typia.assert(page2);

  TestValidator.equals(
    "pagination current page is 2",
    page2.pagination.current,
    2,
  );

  // Step 10: Verify response metadata completeness
  const allImages = await api.functional.discussionBoard.articles.images.index(
    guestConnection,
    {
      articleId: article.id,
      body: {
        page: 1,
        limit: 20,
      } satisfies IDiscussionBoardArticleImage.IRequest,
    },
  );
  typia.assert(allImages);

  TestValidator.predicate(
    "all images have complete metadata",
    allImages.data.every(
      (img) =>
        img.id !== undefined &&
        img.url !== undefined &&
        img.original_name !== undefined &&
        img.mime_type !== undefined &&
        img.size_bytes !== undefined &&
        img.width !== undefined &&
        img.height !== undefined &&
        img.created_at !== undefined,
    ),
  );

  // Verify soft-deleted images are excluded
  TestValidator.predicate(
    "soft-deleted images are excluded from results",
    allImages.data.every(
      (img) => img.deleted_at === null || img.deleted_at === undefined,
    ),
  );

  TestValidator.equals(
    "total records match uploaded images count",
    allImages.pagination.records,
    uploadedImages.length,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleDocument } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleDocument";
import type { IDiscussionBoardArticleImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleImage";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticleImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticleImage";

/**
 * Test pagination and sorting capabilities for article image listings.
 *
 * This validates that users can efficiently navigate through articles with many
 * image attachments using different sorting criteria including upload date,
 * file size, and dimensions.
 *
 * Workflow:
 *
 * 1. Create member account for article and image operations
 * 2. Create moderator account for category creation
 * 3. Create category as moderator
 * 4. Re-authenticate as member
 * 5. Create article as member
 * 6. Upload 10 images with varied properties
 * 7. Test pagination with page size 5
 * 8. Test various sorting options
 * 9. Validate metadata and ordering
 */
export async function test_api_article_images_pagination_and_sorting(
  connection: api.IConnection,
) {
  // Step 1: Create member account
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(12) + "A1!";
  const member = await api.functional.auth.member.join(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: memberEmail,
      password: memberPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardMember.IJoin,
  });
  typia.assert(member);

  // Step 2: Create moderator account
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: moderatorEmail,
      password: RandomGenerator.alphaNumeric(12) + "A1!",
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 3: Create category as moderator
  const category =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: {
          name: RandomGenerator.name(2),
          description: RandomGenerator.paragraph({ sentences: 3 }),
        } satisfies IDiscussionBoardCategory.ICreate,
      },
    );
  typia.assert(category);

  // Step 4: Create article as member
  const article = await api.functional.discussionBoard.member.articles.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({ sentences: 2 }),
        body: RandomGenerator.content({ paragraphs: 3 }),
        summary: RandomGenerator.paragraph({ sentences: 1 }),
        category_ids: [category.id],
      } satisfies IDiscussionBoardArticle.ICreate,
    },
  );
  typia.assert(article);

  // Step 5: Upload 10 images with varied properties
  const imageFormats = [
    "image/jpeg",
    "image/png",
    "image/gif",
    "image/webp",
  ] as const;
  const uploadedImages: IDiscussionBoardArticleImage[] = [];

  for (let i = 0; i < 10; i++) {
    const width = typia.random<
      number & tags.Type<"int32"> & tags.Minimum<50> & tags.Maximum<8000>
    >();
    const height = typia.random<
      number & tags.Type<"int32"> & tags.Minimum<50> & tags.Maximum<8000>
    >();
    const sizeBytes = typia.random<
      number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<5242880>
    >();
    const mimeType = RandomGenerator.pick(imageFormats);

    const image =
      await api.functional.discussionBoard.member.articles.images.create(
        connection,
        {
          articleId: article.id,
          body: {
            url: typia.random<string & tags.Format<"uri">>(),
            original_name: `image_${i}_${RandomGenerator.alphaNumeric(8)}.${mimeType.split("/")[1]}`,
            mime_type: mimeType,
            size_bytes: sizeBytes,
            width: width,
            height: height,
          } satisfies IDiscussionBoardArticleImage.ICreate,
        },
      );
    typia.assert(image);
    uploadedImages.push(image);
  }

  // Step 6: Test pagination - first page with page size 5
  const firstPage = await api.functional.discussionBoard.articles.images.index(
    connection,
    {
      articleId: article.id,
      body: {
        page: 1,
        limit: 5,
      } satisfies IDiscussionBoardArticleImage.IRequest,
    },
  );
  typia.assert(firstPage);

  TestValidator.equals(
    "first page should have 5 items",
    firstPage.data.length,
    5,
  );
  TestValidator.equals(
    "total records should be 10",
    firstPage.pagination.records,
    10,
  );
  TestValidator.equals(
    "total pages should be 2",
    firstPage.pagination.pages,
    2,
  );
  TestValidator.equals(
    "current page should be 1",
    firstPage.pagination.current,
    1,
  );

  // Step 7: Retrieve second page to verify pagination continuity
  const secondPage = await api.functional.discussionBoard.articles.images.index(
    connection,
    {
      articleId: article.id,
      body: {
        page: 2,
        limit: 5,
      } satisfies IDiscussionBoardArticleImage.IRequest,
    },
  );
  typia.assert(secondPage);

  TestValidator.equals(
    "second page should have 5 items",
    secondPage.data.length,
    5,
  );
  TestValidator.equals(
    "second page current should be 2",
    secondPage.pagination.current,
    2,
  );

  // Verify no duplicate images between pages
  const firstPageIds = firstPage.data.map((img) => img.id);
  const secondPageIds = secondPage.data.map((img) => img.id);
  const hasNoDuplicates = firstPageIds.every(
    (id) => !secondPageIds.includes(id),
  );
  TestValidator.predicate(
    "pages should have no duplicate images",
    hasNoDuplicates,
  );

  // Step 8: Test sorting by upload date - newest first (descending)
  const sortedByDateDesc =
    await api.functional.discussionBoard.articles.images.index(connection, {
      articleId: article.id,
      body: {
        sort_by: "created_at",
        sort_order: "desc",
      } satisfies IDiscussionBoardArticleImage.IRequest,
    });
  typia.assert(sortedByDateDesc);

  // Verify descending order by created_at
  for (let i = 0; i < sortedByDateDesc.data.length - 1; i++) {
    const current = new Date(sortedByDateDesc.data[i].created_at).getTime();
    const next = new Date(sortedByDateDesc.data[i + 1].created_at).getTime();
    TestValidator.predicate(
      `image ${i} created_at should be >= image ${i + 1}`,
      current >= next,
    );
  }

  // Test sorting by upload date - oldest first (ascending)
  const sortedByDateAsc =
    await api.functional.discussionBoard.articles.images.index(connection, {
      articleId: article.id,
      body: {
        sort_by: "created_at",
        sort_order: "asc",
      } satisfies IDiscussionBoardArticleImage.IRequest,
    });
  typia.assert(sortedByDateAsc);

  // Verify ascending order by created_at
  for (let i = 0; i < sortedByDateAsc.data.length - 1; i++) {
    const current = new Date(sortedByDateAsc.data[i].created_at).getTime();
    const next = new Date(sortedByDateAsc.data[i + 1].created_at).getTime();
    TestValidator.predicate(
      `image ${i} created_at should be <= image ${i + 1} in ascending`,
      current <= next,
    );
  }

  // Step 9: Test sorting by file size - largest first (descending)
  const sortedBySizeDesc =
    await api.functional.discussionBoard.articles.images.index(connection, {
      articleId: article.id,
      body: {
        sort_by: "size_bytes",
        sort_order: "desc",
      } satisfies IDiscussionBoardArticleImage.IRequest,
    });
  typia.assert(sortedBySizeDesc);

  // Verify descending order by size_bytes
  for (let i = 0; i < sortedBySizeDesc.data.length - 1; i++) {
    TestValidator.predicate(
      `image ${i} size should be >= image ${i + 1}`,
      sortedBySizeDesc.data[i].size_bytes >=
        sortedBySizeDesc.data[i + 1].size_bytes,
    );
  }

  // Test sorting by file size - smallest first (ascending)
  const sortedBySizeAsc =
    await api.functional.discussionBoard.articles.images.index(connection, {
      articleId: article.id,
      body: {
        sort_by: "size_bytes",
        sort_order: "asc",
      } satisfies IDiscussionBoardArticleImage.IRequest,
    });
  typia.assert(sortedBySizeAsc);

  // Verify ascending order by size_bytes
  for (let i = 0; i < sortedBySizeAsc.data.length - 1; i++) {
    TestValidator.predicate(
      `image ${i} size should be <= image ${i + 1} in ascending`,
      sortedBySizeAsc.data[i].size_bytes <=
        sortedBySizeAsc.data[i + 1].size_bytes,
    );
  }

  // Step 10: Test sorting by width - descending
  const sortedByWidthDesc =
    await api.functional.discussionBoard.articles.images.index(connection, {
      articleId: article.id,
      body: {
        sort_by: "width",
        sort_order: "desc",
      } satisfies IDiscussionBoardArticleImage.IRequest,
    });
  typia.assert(sortedByWidthDesc);

  // Verify descending order by width
  for (let i = 0; i < sortedByWidthDesc.data.length - 1; i++) {
    TestValidator.predicate(
      `image ${i} width should be >= image ${i + 1}`,
      sortedByWidthDesc.data[i].width >= sortedByWidthDesc.data[i + 1].width,
    );
  }

  // Test sorting by height - ascending
  const sortedByHeightAsc =
    await api.functional.discussionBoard.articles.images.index(connection, {
      articleId: article.id,
      body: {
        sort_by: "height",
        sort_order: "asc",
      } satisfies IDiscussionBoardArticleImage.IRequest,
    });
  typia.assert(sortedByHeightAsc);

  // Verify ascending order by height
  for (let i = 0; i < sortedByHeightAsc.data.length - 1; i++) {
    TestValidator.predicate(
      `image ${i} height should be <= image ${i + 1} in ascending`,
      sortedByHeightAsc.data[i].height <= sortedByHeightAsc.data[i + 1].height,
    );
  }

  // Step 11: Validate all 10 images are retrievable without pagination
  const allImages = await api.functional.discussionBoard.articles.images.index(
    connection,
    {
      articleId: article.id,
      body: {
        limit: 100,
      } satisfies IDiscussionBoardArticleImage.IRequest,
    },
  );
  typia.assert(allImages);

  TestValidator.equals(
    "all images count should be 10",
    allImages.data.length,
    10,
  );
  TestValidator.equals(
    "pagination records should be 10",
    allImages.pagination.records,
    10,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
