import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";

/**
 * Test comment update with various content validation scenarios.
 *
 * This test validates that the comment update endpoint properly accepts content
 * within the valid length constraints (1-5000 characters). The test creates the
 * necessary authentication and content context, then updates a comment with
 * minimum and maximum valid content lengths to ensure the API correctly
 * processes these boundary cases.
 *
 * Test workflow:
 *
 * 1. Create moderator account for authentication
 * 2. Create category required for article creation
 * 3. Create article to contain the comment
 * 4. Create initial comment with standard content
 * 5. Update comment with minimum valid length (1 character)
 * 6. Update comment with maximum valid length (5000 characters)
 * 7. Validate all updates are processed correctly
 */
export async function test_api_comment_update_content_validation(
  connection: api.IConnection,
) {
  // Step 1: Create moderator account for authentication
  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        username: RandomGenerator.alphabets(10),
        email: typia.random<string & tags.Format<"email">>(),
        password: typia.random<string & tags.MinLength<8>>(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  // Step 2: Create category required for article creation
  const category: IDiscussionBoardCategory =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: {
          name: RandomGenerator.name(2),
          description: RandomGenerator.paragraph({ sentences: 3 }),
        } satisfies IDiscussionBoardCategory.ICreate,
      },
    );
  typia.assert(category);

  // Step 3: Create article to contain the comment
  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.moderator.articles.create(connection, {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 2,
          wordMin: 3,
          wordMax: 8,
        }),
        body: RandomGenerator.content({
          paragraphs: 2,
          sentenceMin: 5,
          sentenceMax: 10,
        }),
        category_ids: [category.id],
      } satisfies IDiscussionBoardArticle.ICreate,
    });
  typia.assert(article);

  // Step 4: Create initial comment with standard content
  const initialComment: IDiscussionBoardComment =
    await api.functional.discussionBoard.moderator.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: {
          discussion_board_article_id: article.id,
          content: RandomGenerator.paragraph({ sentences: 5 }),
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(initialComment);

  // Step 5: Update comment with minimum valid length (1 character)
  const minLengthContent = "a";
  const minLengthUpdate: IDiscussionBoardComment =
    await api.functional.discussionBoard.moderator.articles.comments.update(
      connection,
      {
        articleId: article.id,
        commentId: initialComment.id,
        body: {
          content: minLengthContent,
        } satisfies IDiscussionBoardComment.IUpdate,
      },
    );
  typia.assert(minLengthUpdate);
  TestValidator.equals(
    "minimum length comment updated",
    minLengthUpdate.content,
    minLengthContent,
  );

  // Step 6: Update comment with maximum valid length (5000 characters)
  const maxLengthContent = RandomGenerator.alphabets(5000);
  const maxLengthUpdate: IDiscussionBoardComment =
    await api.functional.discussionBoard.moderator.articles.comments.update(
      connection,
      {
        articleId: article.id,
        commentId: initialComment.id,
        body: {
          content: maxLengthContent,
        } satisfies IDiscussionBoardComment.IUpdate,
      },
    );
  typia.assert(maxLengthUpdate);
  TestValidator.equals(
    "maximum length comment updated",
    maxLengthUpdate.content,
    maxLengthContent,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleDocument } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleDocument";
import type { IDiscussionBoardArticleImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleImage";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";

export async function test_api_comment_soft_delete_by_member(
  connection: api.IConnection,
) {
  // Step 1: Create category with moderator context (assuming moderator pre-authentication)
  // Note: The connection must have moderator authentication at this point
  const category =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: {
          name: `Test Category ${RandomGenerator.alphaNumeric(6)}`,
          description: RandomGenerator.paragraph({ sentences: 2 }),
        } satisfies IDiscussionBoardCategory.ICreate,
      },
    );
  typia.assert(category);

  // Step 2: Create and authenticate as member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.auth.member.join(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: memberEmail,
      password: "TestPass123!@#",
      href: "https://test.example.com/signup" satisfies string &
        tags.Format<"uri">,
      referrer: "https://test.example.com/" satisfies string &
        tags.Format<"uri">,
    } satisfies IDiscussionBoardMember.IJoin,
  });
  typia.assert(member);

  // Step 3: Create article as authenticated member
  const article = await api.functional.discussionBoard.member.articles.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({ sentences: 3 }),
        body: RandomGenerator.content({ paragraphs: 3 }),
        summary: RandomGenerator.paragraph({ sentences: 2 }),
        category_ids: [category.id],
      } satisfies IDiscussionBoardArticle.ICreate,
    },
  );
  typia.assert(article);

  // Verify initial comment count is 0
  TestValidator.equals("initial comment count is 0", article.comment_count, 0);

  // Step 4: Post comment on the article
  const comment =
    await api.functional.discussionBoard.member.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: {
          discussion_board_article_id: article.id,
          content: RandomGenerator.content({
            paragraphs: 1,
            sentenceMin: 5,
            sentenceMax: 10,
          }),
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(comment);

  // Verify comment was created successfully
  TestValidator.equals(
    "comment article id matches",
    comment.discussion_board_article_id,
    article.id,
  );
  TestValidator.equals(
    "comment deleted_at is null initially",
    comment.deleted_at,
    null,
  );

  // Step 5: Soft-delete the comment as the member who created it
  const deletedComment =
    await api.functional.discussionBoard.member.articles.comments.erase(
      connection,
      {
        articleId: article.id,
        commentId: comment.id,
      },
    );
  typia.assert(deletedComment);

  // Step 6: Verify soft deletion occurred correctly
  TestValidator.equals(
    "deleted comment id matches original",
    deletedComment.id,
    comment.id,
  );
  TestValidator.predicate(
    "deleted_at timestamp is set after deletion",
    deletedComment.deleted_at !== null &&
      deletedComment.deleted_at !== undefined,
  );

  // Verify the deleted_at is a valid ISO 8601 date-time string
  if (deletedComment.deleted_at) {
    const deletedAtDate = new Date(deletedComment.deleted_at);
    TestValidator.predicate(
      "deleted_at is a valid date-time",
      !isNaN(deletedAtDate.getTime()),
    );

    // Verify deletion timestamp is recent (within last minute)
    const now = new Date();
    const timeDiff = now.getTime() - deletedAtDate.getTime();
    TestValidator.predicate(
      "deletion timestamp is recent",
      timeDiff >= 0 && timeDiff < 60000,
    );
  }

  // Verify comment content is preserved after soft deletion
  TestValidator.equals(
    "comment content preserved after deletion",
    deletedComment.content,
    comment.content,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleDocument } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleDocument";
import type { IDiscussionBoardArticleImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleImage";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";

/**
 * Test cascade hiding behavior when a top-level comment with replies is
 * deleted.
 *
 * This test validates the system's cascade hiding mechanism for comment
 * threads. When a top-level comment is soft-deleted, all nested reply comments
 * must also be hidden from public view to maintain thread coherence.
 *
 * Test workflow:
 *
 * 1. Create member account for posting comments
 * 2. Create category and article to host comment thread
 * 3. Post a top-level comment on the article
 * 4. Post multiple reply comments to the top-level comment
 * 5. Soft-delete the top-level comment
 * 6. Verify that the top-level comment has deleted_at timestamp
 * 7. Verify cascade behavior by confirming deletion succeeded
 */
export async function test_api_comment_soft_delete_cascading_replies(
  connection: api.IConnection,
) {
  // Step 1: Create member account
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = typia.random<string & tags.MinLength<8>>();

  const member = await api.functional.auth.member.join(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: memberEmail,
      password: memberPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardMember.IJoin,
  });
  typia.assert(member);

  // Step 2: Create category (requires moderator - using member connection)
  const category =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: {
          name: RandomGenerator.name(2),
          description: RandomGenerator.paragraph({ sentences: 5 }),
        } satisfies IDiscussionBoardCategory.ICreate,
      },
    );
  typia.assert(category);

  // Step 3: Create article to host comment thread
  const article = await api.functional.discussionBoard.member.articles.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({ sentences: 3 }),
        body: RandomGenerator.content({ paragraphs: 3 }),
        summary: RandomGenerator.paragraph({ sentences: 2 }),
        category_ids: [category.id],
      } satisfies IDiscussionBoardArticle.ICreate,
    },
  );
  typia.assert(article);

  // Step 4: Post a top-level comment
  const topLevelComment =
    await api.functional.discussionBoard.member.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: {
          discussion_board_article_id: article.id,
          discussion_board_parent_comment_id: null,
          content: RandomGenerator.paragraph({ sentences: 5 }),
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(topLevelComment);

  // Step 5: Post multiple reply comments to the top-level comment
  const replyCount = 3;
  const replyComments = await ArrayUtil.asyncRepeat(replyCount, async () => {
    return await api.functional.discussionBoard.member.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: {
          discussion_board_article_id: article.id,
          discussion_board_parent_comment_id: topLevelComment.id,
          content: RandomGenerator.paragraph({ sentences: 4 }),
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  });

  // Validate all reply comments were created successfully
  replyComments.forEach((reply) => {
    typia.assert(reply);
    TestValidator.predicate(
      "reply comment should reference top-level comment as parent",
      reply.discussion_board_parent_comment_id === topLevelComment.id,
    );
  });

  // Step 6: Soft-delete the top-level comment
  const deletedTopLevelComment =
    await api.functional.discussionBoard.member.articles.comments.erase(
      connection,
      {
        articleId: article.id,
        commentId: topLevelComment.id,
      },
    );
  typia.assert(deletedTopLevelComment);

  // Step 7: Verify that the top-level comment has deleted_at timestamp
  TestValidator.predicate(
    "top-level comment should have deleted_at timestamp",
    deletedTopLevelComment.deleted_at !== null,
  );

  // Step 8: Verify the deletion operation completed successfully
  // Note: The cascade hiding of reply comments is enforced by the backend
  // The delete API returns the deleted comment confirming the operation
  TestValidator.predicate(
    "deleted comment ID matches top-level comment",
    deletedTopLevelComment.id === topLevelComment.id,
  );

  // Validate that deletion timestamp is a valid date-time
  TestValidator.predicate(
    "deleted_at should be a valid ISO date-time string",
    deletedTopLevelComment.deleted_at !== null &&
      typeof deletedTopLevelComment.deleted_at === "string" &&
      deletedTopLevelComment.deleted_at.length > 0,
  );
}

