  await TestValidator.error(
    "previously valid session should be rejected after account deletion",
    async () => {
      await api.functional.discussionBoard.moderator.moderators.erase(
        connection,
        {
          moderatorUsername: deletedModerator.username,
        },
      );
    },
  );
}

