import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAction";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardUserWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserWarning";

/**
 * Test the warning system's support for different severity levels and
 * progressive discipline tracking.
 *
 * This test validates that moderators can issue warnings with different
 * severity classifications (minor, moderate, severe) and that the system
 * properly tracks multiple warnings for the same member to support progressive
 * discipline enforcement. The test ensures severity levels are correctly
 * recorded and multiple warnings are associated with the same member for
 * violation history tracking.
 *
 * Test workflow:
 *
 * 1. Create and authenticate a moderator account
 * 2. Create a member account who will receive warnings
 * 3. Issue a minor severity warning for a first-time violation
 * 4. Validate the minor warning is created with correct severity
 * 5. Issue a moderate severity warning for an escalated violation
 * 6. Validate the moderate warning is created with correct severity
 * 7. Verify both warnings are associated with the same member
 * 8. Validate severity levels are properly recorded for progressive discipline
 */
export async function test_api_warning_creation_with_severity_levels(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate a moderator account
  const moderatorData = {
    username: RandomGenerator.alphaNumeric(12),
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.MinLength<8>>(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardModerator.ICreate;

  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: moderatorData,
    });
  typia.assert(moderator);

  // Step 2: Create a member account who will receive warnings
  const memberData = {
    username: RandomGenerator.alphaNumeric(10),
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.MinLength<8>>(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMember.ICreate;

  const member: IDiscussionBoardMember.ISummary =
    await api.functional.discussionBoard.members.create(connection, {
      body: memberData,
    });
  typia.assert(member);

  // Step 3: Issue a minor severity warning for first-time violation
  const minorWarningData = {
    discussion_board_member_id: member.id,
    warning_reason: "off-topic content",
    warning_details:
      "Your comment on the economic policy article was not related to the topic being discussed. Please keep discussions focused on the subject matter to maintain productive conversations.",
    severity: "minor",
  } satisfies IDiscussionBoardUserWarning.ICreate;

  const minorWarning: IDiscussionBoardUserWarning =
    await api.functional.discussionBoard.moderator.moderation.warnings.create(
      connection,
      {
        body: minorWarningData,
      },
    );
  typia.assert(minorWarning);

  // Step 4: Validate the minor warning is created correctly
  TestValidator.equals(
    "minor warning member ID matches",
    minorWarning.discussion_board_member_id,
    member.id,
  );
  TestValidator.equals(
    "minor warning severity is correct",
    minorWarning.severity,
    "minor",
  );
  TestValidator.equals(
    "minor warning reason is correct",
    minorWarning.warning_reason,
    "off-topic content",
  );

  // Step 5: Issue a moderate severity warning for escalated violation
  const moderateWarningData = {
    discussion_board_member_id: member.id,
    warning_reason: "inappropriate language",
    warning_details:
      "Your recent comment contained disrespectful language toward another member. This is a repeated violation following your previous warning. Please maintain a respectful tone in all discussions or further action will be taken.",
    severity: "moderate",
  } satisfies IDiscussionBoardUserWarning.ICreate;

  const moderateWarning: IDiscussionBoardUserWarning =
    await api.functional.discussionBoard.moderator.moderation.warnings.create(
      connection,
      {
        body: moderateWarningData,
      },
    );
  typia.assert(moderateWarning);

  // Step 6: Validate the moderate warning is created correctly
  TestValidator.equals(
    "moderate warning member ID matches",
    moderateWarning.discussion_board_member_id,
    member.id,
  );
  TestValidator.equals(
    "moderate warning severity is correct",
    moderateWarning.severity,
    "moderate",
  );
  TestValidator.equals(
    "moderate warning reason is correct",
    moderateWarning.warning_reason,
    "inappropriate language",
  );

  // Step 7: Verify both warnings are associated with the same member for progressive discipline
  TestValidator.equals(
    "both warnings target same member",
    minorWarning.discussion_board_member_id,
    moderateWarning.discussion_board_member_id,
  );
  TestValidator.predicate(
    "warnings have different severity levels",
    minorWarning.severity !== moderateWarning.severity,
  );

  // Step 8: Validate severity levels are properly recorded
  TestValidator.predicate(
    "minor severity is recorded",
    minorWarning.severity === "minor",
  );
  TestValidator.predicate(
    "moderate severity is recorded",
    moderateWarning.severity === "moderate",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAction";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardUserWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserWarning";

/**
 * Test that members can retrieve and view detailed information about warnings
 * issued to their own account.
 *
 * This test validates member access to their violation history for transparency
 * and understanding of guideline violations.
 *
 * Workflow:
 *
 * 1. Create moderator account who will issue the warning
 * 2. Create member account who will receive and view the warning
 * 3. Moderator issues a warning to the member with specific violation details
 * 4. Member retrieves the warning details using their authentication
 * 5. Validate complete warning information is returned
 */
export async function test_api_member_view_own_warning_details(
  connection: api.IConnection,
) {
  // Step 1: Create moderator account
  const moderatorData = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    password: "SecurePass123!",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardModerator.ICreate;

  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: moderatorData,
    });
  typia.assert(moderator);

  // Step 2: Create member account via join
  const memberData = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    password: "MemberPass456!",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMember.IJoin;

  const member: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: memberData,
    });
  typia.assert(member);

  // Step 3: Moderator issues warning to the member
  const warningData = {
    discussion_board_member_id: member.id,
    warning_reason: "inappropriate language",
    warning_details:
      "Your comment contained offensive language that violates our community guidelines. Please keep discussions respectful and professional in future posts.",
    severity: "moderate",
  } satisfies IDiscussionBoardUserWarning.ICreate;

  const issuedWarning: IDiscussionBoardUserWarning =
    await api.functional.discussionBoard.moderator.moderation.warnings.create(
      connection,
      {
        body: warningData,
      },
    );
  typia.assert(issuedWarning);

  // Step 4: Member retrieves their warning details
  const retrievedWarning: IDiscussionBoardUserWarning =
    await api.functional.discussionBoard.member.moderation.warnings.at(
      connection,
      {
        warningId: issuedWarning.id,
      },
    );
  typia.assert(retrievedWarning);

  // Step 5: Validate complete warning information
  TestValidator.equals(
    "warning ID matches",
    retrievedWarning.id,
    issuedWarning.id,
  );

  TestValidator.equals(
    "warning reason is correct",
    retrievedWarning.warning_reason,
    warningData.warning_reason,
  );

  TestValidator.equals(
    "warning details are complete",
    retrievedWarning.warning_details,
    warningData.warning_details,
  );

  TestValidator.equals(
    "severity level is correct",
    retrievedWarning.severity,
    warningData.severity,
  );

  TestValidator.equals(
    "warned member ID matches",
    retrievedWarning.discussion_board_member_id,
    member.id,
  );

  TestValidator.equals(
    "issuing moderator ID matches",
    retrievedWarning.discussion_board_moderator_id,
    moderator.id,
  );

  TestValidator.equals(
    "warned user summary ID matches",
    retrievedWarning.warnedUser.id,
    member.id,
  );

  TestValidator.equals(
    "warned user username matches",
    retrievedWarning.warnedUser.username,
    member.username,
  );

  TestValidator.equals(
    "issuing moderator summary ID matches",
    retrievedWarning.issuingModerator.id,
    moderator.id,
  );

  TestValidator.equals(
    "issuing moderator username matches",
    retrievedWarning.issuingModerator.username,
    moderator.username,
  );

  TestValidator.predicate(
    "warning has creation timestamp",
    retrievedWarning.created_at !== null &&
      retrievedWarning.created_at !== undefined,
  );

  TestValidator.predicate(
    "created_at is valid date-time format",
    /^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])(T|\s)([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]/.test(
      retrievedWarning.created_at,
    ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAction";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardUserWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserWarning";

export async function test_api_moderator_view_member_warning_for_review(
  connection: api.IConnection,
) {
  // Step 1: Create first moderator account who will issue the warning
  const issuingModeratorEmail = typia.random<string & tags.Format<"email">>();
  const issuingModerator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        username: typia.random<
          string &
            tags.MinLength<3> &
            tags.MaxLength<30> &
            tags.Pattern<"^[a-zA-Z0-9_-]+$">
        >(),
        email: issuingModeratorEmail,
        password: typia.random<string & tags.MinLength<8>>(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(issuingModerator);

  // Step 2: Create second moderator account who will review the warning
  const reviewingModeratorEmail = typia.random<string & tags.Format<"email">>();
  const reviewingModerator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        username: typia.random<
          string &
            tags.MinLength<3> &
            tags.MaxLength<30> &
            tags.Pattern<"^[a-zA-Z0-9_-]+$">
        >(),
        email: reviewingModeratorEmail,
        password: typia.random<string & tags.MinLength<8>>(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(reviewingModerator);

  // Step 3: Create a member account who will receive the warning
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: {
        username: typia.random<
          string &
            tags.MinLength<3> &
            tags.MaxLength<30> &
            tags.Pattern<"^[a-zA-Z0-9_-]+$">
        >(),
        email: memberEmail,
        password: typia.random<string & tags.MinLength<8>>(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardMember.IJoin,
    });
  typia.assert(member);

  // Switch back to first moderator context (already authenticated)
  connection.headers = {};
  connection.headers.Authorization = issuingModerator.token.access;

  // Step 4: First moderator issues a warning to the member
  const severityOptions = ["minor", "moderate", "severe"] as const;
  const warning: IDiscussionBoardUserWarning =
    await api.functional.discussionBoard.moderator.moderation.warnings.create(
      connection,
      {
        body: {
          discussion_board_member_id: member.id,
          warning_reason: "spam",
          warning_details:
            "Posted promotional content multiple times in violation of community guidelines. Please refrain from advertising products or services in discussion threads.",
          severity: RandomGenerator.pick(severityOptions),
        } satisfies IDiscussionBoardUserWarning.ICreate,
      },
    );
  typia.assert(warning);

  // Switch to second moderator (reviewer) context
  connection.headers = {};
  connection.headers.Authorization = reviewingModerator.token.access;

  // Step 5: Second moderator retrieves the warning details for review
  const retrievedWarning: IDiscussionBoardUserWarning =
    await api.functional.discussionBoard.member.moderation.warnings.at(
      connection,
      {
        warningId: warning.id,
      },
    );
  typia.assert(retrievedWarning);

  // Step 6: Validate the response includes complete context
  TestValidator.equals("warning ID matches", retrievedWarning.id, warning.id);
  TestValidator.equals(
    "warned member ID matches",
    retrievedWarning.discussion_board_member_id,
    member.id,
  );
  TestValidator.equals(
    "warning reason matches",
    retrievedWarning.warning_reason,
    warning.warning_reason,
  );
  TestValidator.equals(
    "warning details match",
    retrievedWarning.warning_details,
    warning.warning_details,
  );
  TestValidator.equals(
    "severity level matches",
    retrievedWarning.severity,
    warning.severity,
  );

  // Step 7: Verify warned member information is included
  TestValidator.predicate(
    "warned user information exists",
    retrievedWarning.warnedUser !== null &&
      retrievedWarning.warnedUser !== undefined,
  );
  TestValidator.equals(
    "warned user ID matches",
    retrievedWarning.warnedUser.id,
    member.id,
  );

  // Step 8: Verify issuing moderator information is included
  TestValidator.predicate(
    "issuing moderator information exists",
    retrievedWarning.issuingModerator !== null &&
      retrievedWarning.issuingModerator !== undefined,
  );

  // Step 9: Validate comprehensive view for informed enforcement decisions
  TestValidator.predicate(
    "warning has creation timestamp",
    retrievedWarning.created_at !== null &&
      retrievedWarning.created_at !== undefined,
  );
  TestValidator.predicate(
    "warning has update timestamp",
    retrievedWarning.updated_at !== null &&
      retrievedWarning.updated_at !== undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAction";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardUserWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserWarning";

/**
 * Test retrieving warning details that include acknowledgment status
 * information.
 *
 * This test validates that the warning retrieval shows whether the member has
 * acknowledged receipt of the warning. The workflow proceeds as follows:
 *
 * 1. Create a moderator account via join for issuing warnings
 * 2. Create a member account via join who will receive the warning
 * 3. Moderator issues a warning to the member
 * 4. Retrieve the warning details immediately after issuance
 * 5. Validate the warning shows acknowledgment status (initially unacknowledged)
 * 6. Verify the response includes timestamps for when the warning was issued and
 *    when acknowledged (null if not acknowledged)
 * 7. Validate the complete warning metadata supports tracking member response to
 *    warnings
 *
 * This test validates that warning details include acknowledgment tracking
 * information, the system records whether members have acknowledged warnings,
 * timestamps show both issuance and acknowledgment times, and moderators can
 * see if members have reviewed their warnings for compliance tracking.
 */
export async function test_api_warning_details_with_acknowledgment_status(
  connection: api.IConnection,
) {
  // Step 1: Create a moderator account who will issue the warning
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(12),
        email: moderatorEmail,
        password: RandomGenerator.alphaNumeric(16),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  // Step 2: Create a member account who will receive the warning
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(12),
        email: memberEmail,
        password: RandomGenerator.alphaNumeric(16),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardMember.IJoin,
    });
  typia.assert(member);

  // Step 3: Create member record in the system (required before warning can be issued)
  const memberRecord: IDiscussionBoardMember.ISummary =
    await api.functional.discussionBoard.members.create(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(12),
        email: typia.random<string & tags.Format<"email">>(),
        password: RandomGenerator.alphaNumeric(16),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardMember.ICreate,
    });
  typia.assert(memberRecord);

  // Step 4: Moderator issues a warning to the member
  const warningReason = "harassment";
  const warningDetails =
    "Posted aggressive comments targeting other members in the economics discussion thread. Please maintain respectful discourse focused on ideas rather than personal attacks.";
  const severity = RandomGenerator.pick([
    "minor",
    "moderate",
    "severe",
  ] as const);

  const issuedWarning: IDiscussionBoardUserWarning =
    await api.functional.discussionBoard.moderator.moderation.warnings.create(
      connection,
      {
        body: {
          discussion_board_member_id: memberRecord.id,
          warning_reason: warningReason,
          warning_details: warningDetails,
          severity: severity,
        } satisfies IDiscussionBoardUserWarning.ICreate,
      },
    );
  typia.assert(issuedWarning);

  // Step 5: Retrieve the warning details immediately after issuance
  const retrievedWarning: IDiscussionBoardUserWarning =
    await api.functional.discussionBoard.member.moderation.warnings.at(
      connection,
      {
        warningId: issuedWarning.id,
      },
    );
  typia.assert(retrievedWarning);

  // Step 6: Validate the warning shows acknowledgment status (initially unacknowledged)
  TestValidator.equals(
    "warning ID matches issued warning",
    retrievedWarning.id,
    issuedWarning.id,
  );

  TestValidator.equals(
    "warning reason matches",
    retrievedWarning.warning_reason,
    warningReason,
  );

  TestValidator.equals(
    "warning details match",
    retrievedWarning.warning_details,
    warningDetails,
  );

  TestValidator.equals(
    "severity level matches",
    retrievedWarning.severity,
    severity,
  );

  // Step 7: Verify acknowledged_at is null (member hasn't acknowledged yet)
  TestValidator.equals(
    "acknowledgment status is null initially",
    retrievedWarning.acknowledged_at,
    null,
  );

  // Step 8: Verify timestamps for warning issuance exist
  TestValidator.predicate(
    "created_at timestamp exists",
    retrievedWarning.created_at !== null &&
      retrievedWarning.created_at !== undefined,
  );

  TestValidator.predicate(
    "updated_at timestamp exists",
    retrievedWarning.updated_at !== null &&
      retrievedWarning.updated_at !== undefined,
  );

  // Step 9: Validate member and moderator information is present
  TestValidator.equals(
    "warned member ID matches",
    retrievedWarning.warnedUser.id,
    memberRecord.id,
  );

  TestValidator.equals(
    "issuing moderator ID matches",
    retrievedWarning.issuingModerator.id,
    moderator.id,
  );

  // Step 10: Verify deleted_at is null (warning is active)
  TestValidator.equals(
    "warning is not deleted",
    retrievedWarning.deleted_at,
    null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
