    comment.moderatorAuthor !== null && comment.moderatorAuthor !== undefined,
  );

  if (comment.moderatorAuthor) {
    TestValidator.equals(
      "moderator author ID matches authenticated moderator",
      comment.moderatorAuthor.id,
      moderator.id,
    );
  }
}

