import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";

/**
 * Test retrieval of a comment including complete author information.
 *
 * This test validates that author attribution is properly included with
 * comments through the author_type discriminator pattern. It creates a
 * moderator account, creates supporting entities (category and article), posts
 * a comment as the moderator, and then retrieves the comment to verify complete
 * author information is included without exposing sensitive data.
 *
 * Steps:
 *
 * 1. Create moderator account for authentication and authorship
 * 2. Create category required for article creation
 * 3. Create article to host the comment
 * 4. Post comment as moderator to establish moderator authorship
 * 5. Retrieve comment by ID to verify author information
 * 6. Validate author_type discriminator is "moderator"
 * 7. Verify moderatorAuthor field is populated (mutual exclusivity)
 * 8. Verify memberAuthor field is null (mutual exclusivity)
 */
export async function test_api_comment_retrieval_with_author_details(
  connection: api.IConnection,
) {
  // Step 1: Create moderator account
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "SecurePass123!";
  const moderatorUsername = RandomGenerator.alphaNumeric(12);
  const moderatorDisplayName = RandomGenerator.name(2);

  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      username: moderatorUsername,
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      bio: RandomGenerator.paragraph({ sentences: 3 }),
      location: "Seoul, South Korea",
      website_url: "https://example.com",
      profile_picture_url: "https://example.com/avatar.jpg",
      href: "https://discussion-board.com/auth/moderator/join",
      referrer: "https://discussion-board.com/home",
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 2: Create category for article creation
  const category =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: {
          name: RandomGenerator.name(2),
          description: RandomGenerator.paragraph({ sentences: 2 }),
        } satisfies IDiscussionBoardCategory.ICreate,
      },
    );
  typia.assert(category);

  // Step 3: Create article to host comment
  const article =
    await api.functional.discussionBoard.moderator.articles.create(connection, {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 1,
          wordMin: 5,
          wordMax: 10,
        }),
        body: RandomGenerator.content({ paragraphs: 3 }),
        summary: RandomGenerator.paragraph({ sentences: 2 }),
        category_ids: [category.id],
      } satisfies IDiscussionBoardArticle.ICreate,
    });
  typia.assert(article);

  // Step 4: Post comment as moderator
  const commentContent = RandomGenerator.content({ paragraphs: 2 });
  const createdComment =
    await api.functional.discussionBoard.moderator.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: {
          discussion_board_article_id: article.id,
          discussion_board_parent_comment_id: null,
          content: commentContent,
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(createdComment);

  // Step 5: Retrieve comment by ID
  const retrievedComment =
    await api.functional.discussionBoard.articles.comments.at(connection, {
      articleId: article.id,
      commentId: createdComment.id,
    });
  typia.assert(retrievedComment);

  // Step 6: Validate author_type discriminator is set to "moderator"
  TestValidator.equals(
    "author_type should be moderator",
    retrievedComment.author_type,
    "moderator",
  );

  // Step 7: Verify moderatorAuthor field is populated (mutual exclusivity)
  TestValidator.predicate(
    "moderatorAuthor should be populated",
    retrievedComment.moderatorAuthor !== null &&
      retrievedComment.moderatorAuthor !== undefined,
  );

  // Step 8: Verify memberAuthor field is null (mutual exclusivity)
  TestValidator.equals(
    "memberAuthor should be null for moderator comments",
    retrievedComment.memberAuthor,
    null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleDocument } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleDocument";
import type { IDiscussionBoardArticleImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleImage";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";

/**
 * Test retrieval of an edited comment to verify edit indicators are properly
 * displayed.
 *
 * This test validates that comment modification history is transparent through
 * timestamp tracking. When a comment is edited, the system must maintain the
 * original created_at timestamp while updating the updated_at timestamp to
 * reflect the modification time. This provides users with clear visibility into
 * content edit history.
 *
 * Test workflow:
 *
 * 1. Register a new moderator account
 * 2. Create a category for article organization
 * 3. Create an article to host the comment
 * 4. Post a comment on the article
 * 5. Edit the comment content
 * 6. Retrieve the edited comment
 * 7. Validate edit indicators through timestamp comparison
 */
export async function test_api_comment_retrieval_with_edit_indicator(
  connection: api.IConnection,
) {
  // Step 1: Create a new moderator account
  const moderatorData = {
    username: RandomGenerator.alphabets(10),
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.MinLength<8>>(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardModerator.ICreate;

  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: moderatorData,
    });
  typia.assert(moderator);

  // Step 2: Create a category for article creation
  const categoryData = {
    name: RandomGenerator.name(2),
    description: RandomGenerator.paragraph({ sentences: 3 }),
  } satisfies IDiscussionBoardCategory.ICreate;

  const category: IDiscussionBoardCategory =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: categoryData,
      },
    );
  typia.assert(category);

  // Step 3: Create an article as a moderator
  const articleData = {
    title: RandomGenerator.paragraph({ sentences: 2, wordMin: 3, wordMax: 7 }),
    body: RandomGenerator.content({
      paragraphs: 3,
      sentenceMin: 10,
      sentenceMax: 20,
    }),
    summary: RandomGenerator.paragraph({ sentences: 1 }),
    category_ids: [category.id],
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.moderator.articles.create(connection, {
      body: articleData,
    });
  typia.assert(article);

  // Step 4: Post a comment on the article
  const originalCommentContent = RandomGenerator.paragraph({
    sentences: 5,
    wordMin: 4,
    wordMax: 8,
  });
  const commentData = {
    discussion_board_article_id: article.id,
    discussion_board_parent_comment_id: null,
    content: originalCommentContent,
  } satisfies IDiscussionBoardComment.ICreate;

  const comment: IDiscussionBoardComment =
    await api.functional.discussionBoard.moderator.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: commentData,
      },
    );
  typia.assert(comment);

  // Step 5: Update the comment content (edit the comment)
  const updatedCommentContent = RandomGenerator.paragraph({
    sentences: 6,
    wordMin: 5,
    wordMax: 9,
  });
  const updateData = {
    content: updatedCommentContent,
  } satisfies IDiscussionBoardComment.IUpdate;

  const updatedComment: IDiscussionBoardComment =
    await api.functional.discussionBoard.moderator.articles.comments.update(
      connection,
      {
        articleId: article.id,
        commentId: comment.id,
        body: updateData,
      },
    );
  typia.assert(updatedComment);

  // Step 6: Retrieve the edited comment by its ID
  const retrievedComment: IDiscussionBoardComment =
    await api.functional.discussionBoard.articles.comments.at(connection, {
      articleId: article.id,
      commentId: comment.id,
    });
  typia.assert(retrievedComment);

  // Step 7: Validate created_at and updated_at timestamps are different
  TestValidator.predicate(
    "created_at and updated_at timestamps should differ after edit",
    retrievedComment.created_at !== retrievedComment.updated_at,
  );

  // Step 8: Verify edit indicator is present (updated_at > created_at)
  const createdTime = new Date(retrievedComment.created_at).getTime();
  const updatedTime = new Date(retrievedComment.updated_at).getTime();

  TestValidator.predicate(
    "updated_at should be greater than created_at for edited comment",
    updatedTime > createdTime,
  );

  // Step 9: Verify updated content is returned
  TestValidator.equals(
    "retrieved comment content should match updated content",
    retrievedComment.content,
    updatedCommentContent,
  );

  // Step 10: Verify modification timestamp is accurate
  TestValidator.equals(
    "retrieved comment ID should match original comment ID",
    retrievedComment.id,
    comment.id,
  );

  TestValidator.equals(
    "retrieved comment article ID should match",
    retrievedComment.discussion_board_article_id,
    article.id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleDocument } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleDocument";
import type { IDiscussionBoardArticleImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleImage";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";

/**
 * Test retrieval of a reply comment to verify parent comment reference and
 * threading context.
 *
 * This test validates that when retrieving a reply comment, the response
 * properly includes the parent comment reference
 * (discussion_board_parent_comment_id) and maintains correct threading context.
 * The test establishes a single-level thread structure with a top-level comment
 * and one reply, then verifies the reply retrieval includes all threading
 * metadata.
 *
 * Test workflow:
 *
 * 1. Create moderator account and authenticate
 * 2. Create category for article organization
 * 3. Create article to host comment thread
 * 4. Post top-level comment on the article
 * 5. Post reply comment referencing the top-level comment
 * 6. Retrieve the reply comment using GET endpoint
 * 7. Validate parent comment reference is present
 * 8. Verify threading context and article association
 * 9. Confirm single-level threading structure
 */
export async function test_api_comment_retrieval_with_threading_context(
  connection: api.IConnection,
) {
  // Step 1: Create moderator account for authentication
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorUsername = RandomGenerator.alphaNumeric(12);

  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      username: moderatorUsername,
      email: moderatorEmail,
      password: typia.random<string & tags.MinLength<8>>(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 2: Create category required for article creation
  const category =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: {
          name: RandomGenerator.name(2),
          description: RandomGenerator.paragraph({ sentences: 5 }),
        } satisfies IDiscussionBoardCategory.ICreate,
      },
    );
  typia.assert(category);

  // Step 3: Create article to host the comment thread
  const article =
    await api.functional.discussionBoard.moderator.articles.create(connection, {
      body: {
        title: RandomGenerator.paragraph({ sentences: 3 }),
        body: RandomGenerator.content({ paragraphs: 3 }),
        category_ids: [category.id],
      } satisfies IDiscussionBoardArticle.ICreate,
    });
  typia.assert(article);

  // Step 4: Post a top-level comment on the article
  const topLevelComment =
    await api.functional.discussionBoard.moderator.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: {
          discussion_board_article_id: article.id,
          discussion_board_parent_comment_id: null,
          content: RandomGenerator.paragraph({ sentences: 10 }),
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(topLevelComment);

  // Step 5: Post a reply comment referencing the top-level comment
  const replyComment =
    await api.functional.discussionBoard.moderator.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: {
          discussion_board_article_id: article.id,
          discussion_board_parent_comment_id: topLevelComment.id,
          content: RandomGenerator.paragraph({ sentences: 8 }),
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(replyComment);

  // Step 6: Retrieve the reply comment by its ID using the target GET endpoint
  const retrievedComment =
    await api.functional.discussionBoard.articles.comments.at(connection, {
      articleId: article.id,
      commentId: replyComment.id,
    });
  typia.assert(retrievedComment);

  // Step 7: Validate parent comment reference is included
  TestValidator.predicate(
    "reply comment should have parent comment reference",
    retrievedComment.discussion_board_parent_comment_id !== null &&
      retrievedComment.discussion_board_parent_comment_id !== undefined,
  );

  // Step 8: Verify threading context shows the parent relationship
  TestValidator.equals(
    "parent comment ID should match top-level comment",
    retrievedComment.discussion_board_parent_comment_id,
    topLevelComment.id,
  );

  // Step 9: Verify the reply is associated with the correct article
  TestValidator.equals(
    "reply comment should be associated with correct article",
    retrievedComment.discussion_board_article_id,
    article.id,
  );

  // Step 10: Verify single-level threading structure
  TestValidator.predicate(
    "top-level comment should not have parent reference",
    topLevelComment.discussion_board_parent_comment_id === null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleDocument } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleDocument";
import type { IDiscussionBoardArticleImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleImage";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardComment";

/**
 * Test that guest users can search and retrieve paginated comments for a
 * specific article without authentication.
 *
 * This validates public access to comment discussions on economic and political
 * articles. The test creates an article with a category, posts multiple
 * comments on that article, then performs a search operation to retrieve those
 * comments without authentication.
 *
 * Workflow:
 *
 * 1. Create member account to author the article
 * 2. Create category for article classification
 * 3. Create article with the category
 * 4. Post multiple comments on the article
 * 5. Perform unauthenticated search to retrieve comments
 * 6. Validate response structure, content, and pagination
 */
export async function test_api_article_comments_search_public_access(
  connection: api.IConnection,
) {
  // Step 1: Create member account to author the article
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.auth.member.join(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: memberEmail,
      password: "SecurePass123!@#",
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardMember.IJoin,
  });
  typia.assert(member);

  // Step 2: Create category required for article creation
  const category =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: {
          name: `Economics ${RandomGenerator.alphaNumeric(6)}`,
          description: RandomGenerator.paragraph({ sentences: 3 }),
        } satisfies IDiscussionBoardCategory.ICreate,
      },
    );
  typia.assert(category);

  // Step 3: Create article to hold comments for search testing
  const article = await api.functional.discussionBoard.member.articles.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 2,
          wordMin: 4,
          wordMax: 8,
        }),
        body: RandomGenerator.content({
          paragraphs: 3,
          sentenceMin: 10,
          sentenceMax: 20,
        }),
        summary: RandomGenerator.paragraph({ sentences: 2 }),
        category_ids: [category.id],
      } satisfies IDiscussionBoardArticle.ICreate,
    },
  );
  typia.assert(article);

  // Step 4: Create multiple comments on the article
  const commentContents = ArrayUtil.repeat(
    5,
    (index) =>
      `Comment ${index + 1}: ${RandomGenerator.paragraph({ sentences: 3, wordMin: 5, wordMax: 10 })}`,
  );

  const createdComments = await ArrayUtil.asyncMap(
    commentContents,
    async (content) => {
      const comment =
        await api.functional.discussionBoard.member.articles.comments.create(
          connection,
          {
            articleId: article.id,
            body: {
              discussion_board_article_id: article.id,
              discussion_board_parent_comment_id: null,
              content: content,
            } satisfies IDiscussionBoardComment.ICreate,
          },
        );
      typia.assert(comment);
      return comment;
    },
  );

  // Step 5: Perform unauthenticated search to retrieve comments
  // Create a fresh connection without authentication headers
  const unauthConn: api.IConnection = { ...connection, headers: {} };

  const searchResult =
    await api.functional.discussionBoard.articles.comments.index(unauthConn, {
      articleId: article.id,
      body: {
        discussion_board_article_id: article.id,
        page: 1,
        limit: 10,
        sort_by: "created_at",
        sort_order: "asc",
      } satisfies IDiscussionBoardComment.IRequest,
    });
  typia.assert(searchResult);

  // Step 6: Validate response includes comment content, author information, timestamps, and proper pagination metadata
  TestValidator.predicate(
    "search result should have data array",
    searchResult.data !== undefined && Array.isArray(searchResult.data),
  );

  TestValidator.predicate(
    "search result should have pagination",
    searchResult.pagination !== undefined,
  );

  TestValidator.equals(
    "pagination current page should be 1",
    searchResult.pagination.current,
    1,
  );

  TestValidator.predicate(
    "should return all created comments",
    searchResult.data.length >= createdComments.length,
  );

  // Validate each comment in the response
  searchResult.data.forEach((commentSummary, index) => {
    TestValidator.predicate(
      `comment ${index} should have id`,
      commentSummary.id !== undefined && typeof commentSummary.id === "string",
    );

    TestValidator.predicate(
      `comment ${index} should have content`,
      commentSummary.content !== undefined && commentSummary.content.length > 0,
    );

    TestValidator.predicate(
      `comment ${index} should have author_type`,
      commentSummary.author_type === "member" ||
        commentSummary.author_type === "moderator",
    );

    TestValidator.predicate(
      `comment ${index} should have created_at timestamp`,
      commentSummary.created_at !== undefined,
    );

    TestValidator.predicate(
      `comment ${index} should have updated_at timestamp`,
      commentSummary.updated_at !== undefined,
    );

    // Validate author information is present based on author_type
    if (commentSummary.author_type === "member") {
      TestValidator.predicate(
        `comment ${index} should have memberAuthor when author_type is member`,
        commentSummary.memberAuthor !== null &&
          commentSummary.memberAuthor !== undefined,
      );
    }
  });

  // Step 7: Verify that soft-deleted comments are excluded from results
  // All returned comments should be active (no deleted_at timestamp in full comment entity)
  // Since we're getting ISummary, we validate that all comments we created are present
  const returnedCommentIds = searchResult.data.map((c) => c.id);
  createdComments.forEach((created) => {
    TestValidator.predicate(
      `created comment ${created.id} should be present in search results`,
      returnedCommentIds.includes(created.id),
    );
  });
}

