    "reviewing moderator still assigned",
    resolvedReport.reviewing_moderator_id,
    moderator.id,
  );
  TestValidator.predicate(
    "resolution notes recorded",
    resolvedReport.resolution_notes !== null &&
      resolvedReport.resolution_notes.length > 0,
  );
