  ]);

  const baseUrl = "/storage";

  const data = images.map((image) => {
    const url = `${baseUrl}/article-images/${image.stored_name}` as string &
      tags.Format<"uri">;

    return {
      id: image.id as string & tags.Format<"uuid">,
      url,
