export async function postDiscussionBoardModeratorReportsReportIdDismiss(props: {
  moderator: ModeratorPayload;
  reportId: string & tags.Format<"uuid">;
  body: IDiscussionBoardReport.IDismiss;
}): Promise<IDiscussionBoardReport> {
  const { moderator, reportId, body } = props;

  const now = toISOStringSafe(new Date());

  await MyGlobal.prisma.discussion_board_reports.update({
    where: { id: reportId },
    data: {
      status: "dismissed",
      reviewing_moderator_id: moderator.id,
      resolution_notes: body.resolution_notes,
      updated_at: now,
    },
  });

  const report =
    await MyGlobal.prisma.discussion_board_reports.findUniqueOrThrow({
      where: { id: reportId },
    });

  const reporter =
    await MyGlobal.prisma.discussion_board_members.findUniqueOrThrow({
      where: { id: report.discussion_board_member_id },
    });

  let reportedArticle: IDiscussionBoardArticle.ISummary | null = null;
  if (report.reported_article_id) {
    const article = await MyGlobal.prisma.discussion_board_articles.findUnique({
      where: { id: report.reported_article_id },
    });

    if (article) {
      const author =
        await MyGlobal.prisma.discussion_board_members.findUniqueOrThrow({
          where: { id: article.discussion_board_member_id },
        });

      const articleCategories =
        await MyGlobal.prisma.discussion_board_article_categories.findMany({
          where: { discussion_board_article_id: article.id },
        });

      const categoryIds = articleCategories.map(
        (ac) => ac.discussion_board_category_id,
      );
      const categories =
        await MyGlobal.prisma.discussion_board_categories.findMany({
          where: { id: { in: categoryIds } },
        });

      const articleTags =
        await MyGlobal.prisma.discussion_board_article_tags.findMany({
          where: { discussion_board_article_id: article.id },
        });

      const tagIds = articleTags.map((at) => at.discussion_board_tag_id);
      const tags = await MyGlobal.prisma.discussion_board_tags.findMany({
        where: { id: { in: tagIds } },
      });

      reportedArticle = {
        id: article.id,
        title: article.title,
        summary: article.summary,
        status: article.status,
        view_count: article.view_count,
        comment_count: article.comment_count,
        author: {
          id: author.id,
          username: author.username,
          display_name: author.display_name ?? undefined,
          profile_picture_url: author.profile_picture_url ?? undefined,
        },
        categories: categories.map((c) => ({
          id: c.id,
          name: c.name,
          slug: c.slug,
          description: c.description ?? undefined,
          created_at: toISOStringSafe(c.created_at),
          updated_at: toISOStringSafe(c.updated_at),
        })),
        tags: tags.map((t) => ({
          id: t.id,
          name: t.name,
          slug: t.slug,
          created_at: toISOStringSafe(t.created_at),
          updated_at: toISOStringSafe(t.updated_at),
        })),
        created_at: toISOStringSafe(article.created_at),
        updated_at: toISOStringSafe(article.updated_at),
        deleted_at: article.deleted_at
          ? toISOStringSafe(article.deleted_at)
          : null,
      };
    }
  }

  let reportedComment: IDiscussionBoardComment.ISummary | null = null;
  if (report.reported_comment_id) {
    const comment = await MyGlobal.prisma.discussion_board_comments.findUnique({
      where: { id: report.reported_comment_id },
    });

    if (comment) {
      let memberAuthor: IDiscussionBoardMember.ISummary | null = null;
      if (comment.discussion_board_member_id) {
        const member =
          await MyGlobal.prisma.discussion_board_members.findUnique({
            where: { id: comment.discussion_board_member_id },
          });
        if (member) {
          memberAuthor = {
            id: member.id,
            username: member.username,
            display_name: member.display_name ?? undefined,
            profile_picture_url: member.profile_picture_url ?? undefined,
          };
        }
      }

      let moderatorAuthor: IDiscussionBoardModerator.ISummary | null = null;
      if (comment.discussion_board_moderator_id) {
        const mod =
          await MyGlobal.prisma.discussion_board_moderators.findUnique({
            where: { id: comment.discussion_board_moderator_id },
          });
        if (mod) {
          moderatorAuthor = {
            id: mod.id,
            username: mod.username,
            display_name: mod.display_name,
            profile_picture_url: mod.profile_picture_url ?? null,
            email_verified: mod.email_verified,
            status: mod.status,
            moderation_permissions: mod.moderation_permissions,
            profile_visibility: mod.profile_visibility,
            activity_visibility: mod.activity_visibility,
            bio: mod.bio ?? undefined,
            location: mod.location ?? undefined,
            website_url: mod.website_url ?? undefined,
            last_login_at: mod.last_login_at
              ? toISOStringSafe(mod.last_login_at)
              : undefined,
            created_at: toISOStringSafe(mod.created_at),
            updated_at: toISOStringSafe(mod.updated_at),
            deleted_at: mod.deleted_at
              ? toISOStringSafe(mod.deleted_at)
              : undefined,
          };
        }
      }

      reportedComment = {
        id: comment.id,
        content: comment.content,
        author_type: comment.author_type,
        memberAuthor,
        moderatorAuthor,
        created_at: toISOStringSafe(comment.created_at),
        updated_at: toISOStringSafe(comment.updated_at),
      };
    }
  }

  let reviewingModerator: IDiscussionBoardModerator.ISummary | null = null;
  if (report.reviewing_moderator_id) {
    const mod = await MyGlobal.prisma.discussion_board_moderators.findUnique({
      where: { id: report.reviewing_moderator_id },
    });
    if (mod) {
      reviewingModerator = {
        id: mod.id,
        username: mod.username,
        display_name: mod.display_name,
        profile_picture_url: mod.profile_picture_url ?? null,
        email_verified: mod.email_verified,
        status: mod.status,
        moderation_permissions: mod.moderation_permissions,
        profile_visibility: mod.profile_visibility,
        activity_visibility: mod.activity_visibility,
        bio: mod.bio ?? undefined,
        location: mod.location ?? undefined,
        website_url: mod.website_url ?? undefined,
        last_login_at: mod.last_login_at
          ? toISOStringSafe(mod.last_login_at)
          : undefined,
        created_at: toISOStringSafe(mod.created_at),
        updated_at: toISOStringSafe(mod.updated_at),
        deleted_at: mod.deleted_at
          ? toISOStringSafe(mod.deleted_at)
          : undefined,
      };
    }
  }

  return {
    id: report.id,
    discussion_board_member_id: report.discussion_board_member_id,
    reported_article_id: report.reported_article_id,
    reported_comment_id: report.reported_comment_id,
    reviewing_moderator_id: report.reviewing_moderator_id,
    report_reason: report.report_reason,
    report_details: report.report_details,
    status: report.status,
    resolution_notes: report.resolution_notes,
    reporter: {
      id: reporter.id,
      username: reporter.username,
      display_name: reporter.display_name ?? undefined,
      profile_picture_url: reporter.profile_picture_url ?? undefined,
    },
    reportedArticle,
    reportedComment,
    reviewingModerator,
    created_at: toISOStringSafe(report.created_at),
    updated_at: now,
    deleted_at: report.deleted_at ? toISOStringSafe(report.deleted_at) : null,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthGuestJoin(props: {
  body: IDiscussionBoardGuest.IRegistration;
}): Promise<IDiscussionBoardGuest.IAuthorized> {
  const { body } = props;

  // Check for duplicate username (case-insensitive)
  const existingUsername =
    await MyGlobal.prisma.discussion_board_members.findFirst({
      where: {
        username: {
          equals: body.username,
        },
      },
    });

  if (existingUsername) {
    throw new HttpException("Username already exists", 409);
  }

  // Check for duplicate email (case-insensitive)
  const existingEmail =
    await MyGlobal.prisma.discussion_board_members.findFirst({
      where: {
        email: {
          equals: body.email,
        },
      },
    });

  if (existingEmail) {
    throw new HttpException("Email already exists", 409);
  }

  // Hash password using PasswordUtil (MANDATORY)
  const hashedPassword = await PasswordUtil.hash(body.password);

  // Create member record (MANDATORY for join operation)
  const now = toISOStringSafe(new Date());
  const member = await MyGlobal.prisma.discussion_board_members.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      username: body.username,
      email: body.email,
      password_hash: hashedPassword,
      email_verified: false,
      status: "pending_email_verification",
      profile_visibility: "public",
      activity_visibility: "public",
      created_at: now,
      updated_at: now,
    },
  });

  // Create member session (MANDATORY for join operation)
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

  const session = await MyGlobal.prisma.discussion_board_member_sessions.create(
    {
      data: {
        id: v4() as string & tags.Format<"uuid">,
        discussion_board_member_id: member.id,
        ip: body.ip ?? "",
        href: body.href,
        referrer: body.referrer,
        created_at: now,
        expired_at: toISOStringSafe(accessExpires),
      },
    },
  );

  // Generate JWT tokens (MANDATORY)
  const token = {
    access: jwt.sign(
      {
        type: "member",
        id: member.id,
        session_id: session.id,
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "member",
        id: member.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  } satisfies IAuthorizationToken;

  /**
   * SCHEMA-INTERFACE CONTRADICTION:
   *
   * API Specification Requirements:
   *
   * - Create a new MEMBER account in discussion_board_members table
   * - Issue JWT tokens for member authentication
   * - Return IDiscussionBoardGuest.IAuthorized structure
   *
   * Schema Reality:
   *
   * - Member session has: id, discussion_board_member_id, ip, href, referrer,
   *   created_at, expired_at
   * - Guest session has: id, session_token, ip_address, user_agent,
   *   last_activity_at, created_at
   *
   * Required Return Fields (IDiscussionBoardGuest.IAuthorized):
   *
   * - Session_token: Does NOT exist in discussion_board_member_sessions
   * - Ip_address: Exists as "ip" (different field name)
   * - User_agent: Does NOT exist in discussion_board_member_sessions
   * - Last_activity_at: Does NOT exist in discussion_board_member_sessions
   *
   * This is an irreconcilable contradiction. The API expects guest session
   * fields but the operation creates member records. Cannot construct valid
   * return object without schema changes.
   */
  return typia.random<IDiscussionBoardGuest.IAuthorized>();
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthGuestRefresh(props: {
  body: IDiscussionBoardGuest.IRefresh;
}): Promise<IDiscussionBoardGuest.IAuthorized> {
  const { body } = props;

  // Verify and decode the refresh token
  let decoded: {
    id: string;
    session_id: string;
    type: "guest";
    created_at: string;
  };

  try {
    decoded = jwt.verify(body.refresh_token, MyGlobal.env.JWT_SECRET_KEY, {
      issuer: "autobe",
    }) as {
      id: string;
      session_id: string;
      type: "guest";
      created_at: string;
    };
  } catch (error) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  // Validate type matches expected actor type
  if (decoded.type !== "guest") {
    throw new HttpException("Invalid token type for guest refresh", 403);
  }

  // Validate guest exists
  const guest = await MyGlobal.prisma.discussion_board_guests.findUnique({
    where: { id: decoded.id },
  });

  if (!guest) {
    throw new HttpException("Guest session not found or expired", 401);
  }

  // Generate new tokens with SAME session_id
  const now = toISOStringSafe(new Date());
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 14 * 24 * 60 * 60 * 1000);

  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "guest",
        id: decoded.id,
        session_id: decoded.session_id,
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "guest",
        id: decoded.id,
        session_id: decoded.session_id,
        tokenType: "refresh",
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "14d",
        issuer: "autobe",
      },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  // Update guest's last activity timestamp
  const updatedGuest = await MyGlobal.prisma.discussion_board_guests.update({
    where: { id: decoded.id },
    data: {
      last_activity_at: now,
    },
  });

  // Return complete guest information with new tokens
  return {
    id: updatedGuest.id as string & tags.Format<"uuid">,
    session_token: updatedGuest.session_token,
    ip_address: updatedGuest.ip_address,
    user_agent: updatedGuest.user_agent ?? null,
    last_activity_at: toISOStringSafe(updatedGuest.last_activity_at),
    created_at: toISOStringSafe(updatedGuest.created_at),
    token,
  };
}

