export async function postDiscussionBoardMembers(props: {
  body: IDiscussionBoardMember.ICreate;
}): Promise<IDiscussionBoardMember.ISummary> {
  const { body } = props;

  // Validate username uniqueness
  const existingUsername =
    await MyGlobal.prisma.discussion_board_members.findFirst({
      where: { username: body.username },
    });

  if (existingUsername) {
    throw new HttpException(
      "Username already exists. Please choose a different username.",
      409,
    );
  }

  // Validate email uniqueness
  const existingEmail =
    await MyGlobal.prisma.discussion_board_members.findFirst({
      where: { email: body.email },
    });

  if (existingEmail) {
    throw new HttpException(
      "Email address already registered. Please use a different email or log in.",
      409,
    );
  }

  // Hash password securely
  const passwordHash = await PasswordUtil.hash(body.password);

  // Generate member ID and current timestamp
  const memberId = v4();
  const now = toISOStringSafe(new Date());

  // Create member record with pending email verification status
  const createdMember = await MyGlobal.prisma.discussion_board_members.create({
    data: {
      id: memberId,
      username: body.username,
      email: body.email,
      password_hash: passwordHash,
      display_name: body.display_name ?? null,
      bio: body.bio ?? null,
      location: body.location ?? null,
      website_url: body.website_url ?? null,
      profile_picture_url: body.profile_picture_url ?? null,
      email_verified: false,
      status: "pending_email_verification",
      profile_visibility: "public",
      activity_visibility: "public",
      last_login_at: null,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });

  // Create initial session record for registration tracking
  const sessionId = v4();
  await MyGlobal.prisma.discussion_board_member_sessions.create({
    data: {
      id: sessionId,
      discussion_board_member_id: memberId,
      ip: body.ip ?? "",
      href: body.href,
      referrer: body.referrer,
      created_at: now,
      expired_at: null,
    },
  });

  // Return member summary excluding sensitive authentication data
  return {
    id: createdMember.id,
    username: createdMember.username,
    display_name: createdMember.display_name ?? undefined,
    profile_picture_url: createdMember.profile_picture_url ?? undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { IPageIDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMember";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

export async function patchDiscussionBoardMembers(props: {
  body: IDiscussionBoardMember.IRequest;
}): Promise<IPageIDiscussionBoardMember.ISummary> {
  const { body } = props;

  // Normalize pagination with defaults
  const page = (body.page ?? 1) as number &
    tags.Type<"int32"> &
    tags.Minimum<1> as number;
  const limit = (body.limit ?? 20) as number &
    tags.Type<"int32"> &
    tags.Minimum<10> &
    tags.Maximum<100> as number;
  const skip = (page - 1) * limit;

  // Build search conditions for trigram matching on username, display_name, bio
  const searchConditions =
    body.search !== undefined && body.search !== null && body.search.length >= 2
      ? {
          OR: [
            { username: { contains: body.search } },
            { display_name: { contains: body.search } },
            { bio: { contains: body.search } },
          ],
        }
      : {};

  // Build date range filter
  const dateRangeFilter =
    (body.created_after !== undefined && body.created_after !== null) ||
    (body.created_before !== undefined && body.created_before !== null)
      ? {
          created_at: {
            ...(body.created_after !== undefined &&
              body.created_after !== null && {
                gte: body.created_after,
              }),
            ...(body.created_before !== undefined &&
              body.created_before !== null && {
                lte: body.created_before,
              }),
          },
        }
      : {};

  // Execute parallel count and findMany queries
  const [members, total] = await Promise.all([
    MyGlobal.prisma.discussion_board_members.findMany({
      where: {
        ...searchConditions,
        ...(body.status !== undefined &&
          body.status !== null && {
            status: body.status,
          }),
        ...(body.profile_visibility !== undefined &&
          body.profile_visibility !== null && {
            profile_visibility: body.profile_visibility,
          }),
        ...dateRangeFilter,
      },
      orderBy:
        body.sort_by === "username"
          ? { username: body.sort_order === "asc" ? "asc" : "desc" }
          : body.sort_by === "display_name"
            ? { display_name: body.sort_order === "asc" ? "asc" : "desc" }
            : body.sort_by === "last_login_at"
              ? { last_login_at: body.sort_order === "asc" ? "asc" : "desc" }
              : { created_at: body.sort_order === "asc" ? "asc" : "desc" },
      skip,
      take: limit,
      select: {
        id: true,
        username: true,
        display_name: true,
        profile_picture_url: true,
      },
    }),
    MyGlobal.prisma.discussion_board_members.count({
      where: {
        ...searchConditions,
        ...(body.status !== undefined &&
          body.status !== null && {
            status: body.status,
          }),
        ...(body.profile_visibility !== undefined &&
          body.profile_visibility !== null && {
            profile_visibility: body.profile_visibility,
          }),
        ...dateRangeFilter,
      },
    }),
  ]);

  // Calculate total pages
  const pages = Math.ceil(total / limit);

  // Map to ISummary format with proper null to undefined conversion
  const data = members.map((member) => ({
    id: member.id satisfies string as string & tags.Format<"uuid">,
    username: member.username,
    display_name: member.display_name ?? undefined,
    profile_picture_url: member.profile_picture_url
      ? (member.profile_picture_url satisfies string as string &
          tags.Format<"uri">)
      : undefined,
  }));

  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages,
    },
    data,
  };
}

