            some: { deleted_at: null },
          },
        }),
        ...(body.has_documents === true && {
          discussion_board_article_documents: {
            some: { deleted_at: null },
          },
        }),
      },
      orderBy:
        body.sort_by === "view_count"
          ? { view_count: body.sort_order === "asc" ? "asc" : "desc" }
          : body.sort_by === "comment_count"
            ? { comment_count: body.sort_order === "asc" ? "asc" : "desc" }
            : body.sort_by === "updated_at"
              ? { updated_at: body.sort_order === "asc" ? "asc" : "desc" }
              : body.sort_by === "relevance"
                ? { created_at: "desc" }
                : { created_at: body.sort_order === "asc" ? "asc" : "desc" },
      skip,
      take: limit,
      include: {
        author: true,
        discussion_board_article_categories: {
          include: {
            category: true,
          },
        },
        discussion_board_article_tags: {
          include: {
            tag: true,
          },
        },
      },
    }),
    MyGlobal.prisma.discussion_board_articles.count({
      where: {
        deleted_at: null,
        ...(body.status !== undefined && { status: body.status }),
        ...(body.search !== undefined && {
          OR: [
            { title: { contains: body.search } },
            { body: { contains: body.search } },
          ],
        }),
        ...(body.category_slugs !== undefined &&
          body.category_slugs.length > 0 && {
            discussion_board_article_categories: {
              some: {
                category: {
                  slug: { in: body.category_slugs },
                },
              },
            },
          }),
        ...(body.tag_slugs !== undefined &&
          body.tag_slugs.length > 0 && {
            AND: body.tag_slugs.map((tagSlug) => ({
              discussion_board_article_tags: {
                some: {
                  tag: {
                    slug: tagSlug,
                  },
                },
              },
            })),
          }),
        ...(body.author_username !== undefined && {
          author: {
            username: body.author_username,
          },
        }),
        ...((body.created_after !== undefined ||
          body.created_before !== undefined) && {
          created_at: {
            ...(body.created_after !== undefined && {
              gte: body.created_after,
            }),
            ...(body.created_before !== undefined && {
              lte: body.created_before,
            }),
          },
        }),
        ...((body.min_view_count !== undefined ||
          body.max_view_count !== undefined) && {
          view_count: {
            ...(body.min_view_count !== undefined && {
              gte: body.min_view_count,
            }),
            ...(body.max_view_count !== undefined && {
              lte: body.max_view_count,
            }),
          },
        }),
        ...((body.min_comment_count !== undefined ||
          body.max_comment_count !== undefined) && {
          comment_count: {
            ...(body.min_comment_count !== undefined && {
              gte: body.min_comment_count,
            }),
            ...(body.max_comment_count !== undefined && {
              lte: body.max_comment_count,
            }),
          },
        }),
        ...(body.has_images === true && {
          discussion_board_article_images: {
            some: { deleted_at: null },
          },
        }),
        ...(body.has_documents === true && {
          discussion_board_article_documents: {
            some: { deleted_at: null },
          },
        }),
      },
    }),
  ]);

  const articles = data.map((article) => ({
    id: article.id,
    title: article.title,
    summary: article.summary,
    status: article.status,
    view_count: article.view_count,
    comment_count: article.comment_count,
    author: {
      id: article.author.id,
      username: article.author.username,
      display_name: article.author.display_name,
      profile_picture_url: article.author.profile_picture_url,
    },
    categories: article.discussion_board_article_categories.map((ac) => ({
      id: ac.category.id,
      name: ac.category.name,
      slug: ac.category.slug,
      description: ac.category.description,
      created_at: toISOStringSafe(ac.category.created_at),
      updated_at: toISOStringSafe(ac.category.updated_at),
    })),
    tags: article.discussion_board_article_tags.map((at) => ({
      id: at.tag.id,
      name: at.tag.name,
      slug: at.tag.slug,
      created_at: toISOStringSafe(at.tag.created_at),
      updated_at: toISOStringSafe(at.tag.updated_at),
    })),
    created_at: toISOStringSafe(article.created_at),
    updated_at: toISOStringSafe(article.updated_at),
    deleted_at: article.deleted_at ? toISOStringSafe(article.deleted_at) : null,
  }));

  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: articles,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import { IPageIDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardReport";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function patchDiscussionBoardModeratorReports(props: {
  moderator: ModeratorPayload;
  body: IDiscussionBoardReport.IRequest;
}): Promise<IPageIDiscussionBoardReport.ISummary> {
  const { body } = props;

  // Build where clause with SQLite compatibility (no mode property)
  const whereConditions = {
    deleted_at: null,
    ...(body.discussion_board_member_id !== undefined &&
      body.discussion_board_member_id !== null && {
        discussion_board_member_id: body.discussion_board_member_id,
      }),
    ...(body.status !== undefined &&
      body.status !== null && {
        status: body.status,
      }),
    ...(body.report_reason !== undefined &&
      body.report_reason !== null && {
        report_reason: body.report_reason,
      }),
    ...(body.target_type !== undefined && body.target_type !== null
      ? body.target_type === "article"
        ? { reported_article_id: { not: null } }
        : { reported_comment_id: { not: null } }
      : {}),
    ...((body.from_date !== undefined && body.from_date !== null) ||
    (body.to_date !== undefined && body.to_date !== null)
      ? {
          created_at: {
            ...(body.from_date !== undefined &&
              body.from_date !== null && {
                gte: body.from_date,
              }),
            ...(body.to_date !== undefined &&
              body.to_date !== null && {
                lte: body.to_date,
              }),
          },
        }
      : {}),
    ...(body.reporter_username !== undefined &&
      body.reporter_username !== null && {
        reporter: {
          username: body.reporter_username,
        },
      }),
    ...(body.reviewing_moderator_username !== undefined &&
      body.reviewing_moderator_username !== null && {
        reviewingModerator: {
          username: body.reviewing_moderator_username,
        },
      }),
  };

  // Pagination parameters
  const page = body.page ?? 1;
  const limit = body.limit ?? 50;
  const skip = (Number(page) - 1) * Number(limit);
  const take = Number(limit);

  // Determine sort field and order
  const sortBy = body.sort_by ?? "priority";
  const sortOrder = (body.sort_order ?? "desc") as "asc" | "desc";

  let reports: Array<{
    id: string;
    discussion_board_member_id: string;
    reported_article_id: string | null;
    reported_comment_id: string | null;
    reviewing_moderator_id: string | null;
    report_reason: string;
    report_details: string | null;
    status: string;
    resolution_notes: string | null;
    created_at: Date;
    updated_at: Date;
    deleted_at: Date | null;
    reporter: {
      id: string;
      username: string;
      display_name: string | null;
      profile_picture_url: string | null;
    };
    reviewingModerator: {
      id: string;
      username: string;
      display_name: string | null;
      profile_picture_url: string | null;
      email_verified: boolean;
      status: string;
      moderation_permissions: string;
      profile_visibility: string;
      activity_visibility: string;
      bio: string | null;
      location: string | null;
      website_url: string | null;
      last_login_at: Date | null;
      created_at: Date;
      updated_at: Date;
      deleted_at: Date | null;
    } | null;
  }>;
  let total: number;

  if (sortBy === "priority") {
    // For priority sorting, fetch all reports and sort by count in memory
    const allReports = await MyGlobal.prisma.discussion_board_reports.findMany({
      where: whereConditions,
      include: {
        reporter: {
          select: {
            id: true,
            username: true,
            display_name: true,
            profile_picture_url: true,
          },
        },
        reviewingModerator: {
          select: {
            id: true,
            username: true,
            display_name: true,
            profile_picture_url: true,
            email_verified: true,
            status: true,
            moderation_permissions: true,
            profile_visibility: true,
            activity_visibility: true,
            bio: true,
            location: true,
            website_url: true,
            last_login_at: true,
            created_at: true,
            updated_at: true,
            deleted_at: true,
          },
        },
      },
    });

    // Count reports per target
    const targetCounts = new Map<string, number>();
    for (const report of allReports) {
      const targetId =
        report.reported_article_id || report.reported_comment_id || "";
      targetCounts.set(targetId, (targetCounts.get(targetId) || 0) + 1);
    }

    // Sort by priority
    const sortedReports = allReports.sort((a, b) => {
      const targetA = a.reported_article_id || a.reported_comment_id || "";
      const targetB = b.reported_article_id || b.reported_comment_id || "";
      const countA = targetCounts.get(targetA) || 0;
      const countB = targetCounts.get(targetB) || 0;

      if (sortOrder === "desc") {
        return countB - countA;
      }
      return countA - countB;
    });

    total = sortedReports.length;
    reports = sortedReports.slice(skip, skip + take);
  } else {
    // Database sorting for other fields
    const orderByField =
      sortBy === "created_at"
        ? "created_at"
        : sortBy === "updated_at"
          ? "updated_at"
          : sortBy === "status"
            ? "status"
            : "created_at";

    const [fetchedReports, count] = await Promise.all([
      MyGlobal.prisma.discussion_board_reports.findMany({
        where: whereConditions,
        include: {
          reporter: {
            select: {
              id: true,
              username: true,
              display_name: true,
              profile_picture_url: true,
            },
          },
          reviewingModerator: {
            select: {
              id: true,
              username: true,
              display_name: true,
              profile_picture_url: true,
              email_verified: true,
              status: true,
              moderation_permissions: true,
              profile_visibility: true,
              activity_visibility: true,
              bio: true,
              location: true,
              website_url: true,
              last_login_at: true,
              created_at: true,
              updated_at: true,
              deleted_at: true,
            },
          },
        },
        orderBy: { [orderByField]: sortOrder },
        skip,
        take,
      }),
      MyGlobal.prisma.discussion_board_reports.count({
        where: whereConditions,
      }),
    ]);

    reports = fetchedReports;
    total = count;
  }

  // Map to response format
  const data: IDiscussionBoardReport.ISummary[] = reports.map((report) => {
    const reportedContentType: "article" | "comment" =
      report.reported_article_id !== null ? "article" : "comment";

    return {
      id: report.id,
      reporter: {
        id: report.reporter.id,
        username: report.reporter.username,
        display_name: report.reporter.display_name ?? undefined,
        profile_picture_url: report.reporter.profile_picture_url ?? undefined,
      },
      reported_article_id: report.reported_article_id,
      reported_comment_id: report.reported_comment_id,
      reported_content_type: reportedContentType,
      report_reason: report.report_reason,
      report_details: report.report_details,
      status: report.status as
        | "pending"
        | "under_review"
        | "resolved"
        | "dismissed",
      resolution_notes: report.resolution_notes,
      reviewing_moderator: report.reviewingModerator
        ? {
            id: report.reviewingModerator.id,
            username: report.reviewingModerator.username,
            display_name: report.reviewingModerator.display_name,
            profile_picture_url: report.reviewingModerator.profile_picture_url,
            email_verified: report.reviewingModerator.email_verified,
            status: report.reviewingModerator.status,
            moderation_permissions:
              report.reviewingModerator.moderation_permissions,
            profile_visibility: report.reviewingModerator.profile_visibility,
            activity_visibility: report.reviewingModerator.activity_visibility,
            bio: report.reviewingModerator.bio ?? undefined,
            location: report.reviewingModerator.location ?? undefined,
            website_url: report.reviewingModerator.website_url ?? undefined,
            last_login_at: report.reviewingModerator.last_login_at
              ? toISOStringSafe(report.reviewingModerator.last_login_at)
              : undefined,
            created_at: toISOStringSafe(report.reviewingModerator.created_at),
            updated_at: toISOStringSafe(report.reviewingModerator.updated_at),
            deleted_at: report.reviewingModerator.deleted_at
              ? toISOStringSafe(report.reviewingModerator.deleted_at)
              : undefined,
          }
        : null,
      created_at: toISOStringSafe(report.created_at),
      updated_at: toISOStringSafe(report.updated_at),
      deleted_at: report.deleted_at ? toISOStringSafe(report.deleted_at) : null,
    };
  });

  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: Math.ceil(total / Number(limit)),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function postDiscussionBoardMemberReports(props: {
  member: MemberPayload;
  body: IDiscussionBoardReport.ICreate;
}): Promise<IDiscussionBoardReport> {
  const { member, body } = props;

  // Validate exactly one target is specified
  if (
    (body.reported_article_id === null ||
      body.reported_article_id === undefined) ===
    (body.reported_comment_id === null ||
      body.reported_comment_id === undefined)
  ) {
    throw new HttpException(
      "Exactly one of reported_article_id or reported_comment_id must be provided",
      400,
    );
  }

  // Verify reported content exists
  if (
    body.reported_article_id !== null &&
    body.reported_article_id !== undefined
  ) {
    const article = await MyGlobal.prisma.discussion_board_articles.findFirst({
      where: {
        id: body.reported_article_id,
        deleted_at: null,
      },
    });
    if (!article) {
      throw new HttpException("Reported article not found", 404);
    }
  }

  if (
    body.reported_comment_id !== null &&
    body.reported_comment_id !== undefined
  ) {
    const comment = await MyGlobal.prisma.discussion_board_comments.findFirst({
      where: {
        id: body.reported_comment_id,
        deleted_at: null,
      },
    });
    if (!comment) {
      throw new HttpException("Reported comment not found", 404);
    }
  }

  // Check for duplicate report
  const existingReport =
    await MyGlobal.prisma.discussion_board_reports.findFirst({
      where: {
        discussion_board_member_id: member.id,
        reported_article_id: body.reported_article_id ?? null,
        reported_comment_id: body.reported_comment_id ?? null,
        deleted_at: null,
      },
    });

  if (existingReport) {
    throw new HttpException("You have already reported this content", 409);
  }

  // Prepare timestamp once for reuse
  const now = toISOStringSafe(new Date());

  // Create the report
  const created = await MyGlobal.prisma.discussion_board_reports.create({
    data: {
      id: v4(),
      discussion_board_member_id: member.id,
      reported_article_id: body.reported_article_id ?? null,
      reported_comment_id: body.reported_comment_id ?? null,
      report_reason: body.report_reason,
      report_details: body.report_details ?? null,
      status: "pending",
      reviewing_moderator_id: null,
      resolution_notes: null,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
    include: {
      reporter: true,
      reportedArticle: {
        include: {
          author: true,
          discussion_board_article_categories: {
            include: {
              category: true,
            },
          },
          discussion_board_article_tags: {
            include: {
              tag: true,
            },
          },
        },
      },
      reportedComment: {
        include: {
          memberAuthor: true,
          moderatorAuthor: true,
        },
      },
    },
  });

  // Build reporter summary
  const reporterSummary = {
    id: created.reporter.id,
    username: created.reporter.username,
    display_name: created.reporter.display_name ?? null,
    profile_picture_url: created.reporter.profile_picture_url ?? null,
  } satisfies IDiscussionBoardMember.ISummary;

  // Build reported article summary if applicable
  let reportedArticleSummary: IDiscussionBoardArticle.ISummary | null = null;
  if (created.reportedArticle) {
    const article = created.reportedArticle;
    reportedArticleSummary = {
      id: article.id,
      title: article.title,
      summary: article.summary,
      status: article.status,
      view_count: article.view_count,
      comment_count: article.comment_count,
      author: {
        id: article.author.id,
        username: article.author.username,
        display_name: article.author.display_name ?? null,
        profile_picture_url: article.author.profile_picture_url ?? null,
      },
      categories: article.discussion_board_article_categories.map((ac) => ({
        id: ac.category.id,
        name: ac.category.name,
        slug: ac.category.slug,
        description: ac.category.description ?? null,
        created_at: toISOStringSafe(ac.category.created_at),
        updated_at: toISOStringSafe(ac.category.updated_at),
      })),
      tags: article.discussion_board_article_tags.map((at) => ({
        id: at.tag.id,
        name: at.tag.name,
        slug: at.tag.slug,
        created_at: toISOStringSafe(at.tag.created_at),
        updated_at: toISOStringSafe(at.tag.updated_at),
      })),
      created_at: toISOStringSafe(article.created_at),
      updated_at: toISOStringSafe(article.updated_at),
      deleted_at: article.deleted_at
        ? toISOStringSafe(article.deleted_at)
        : null,
    };
  }

  // Build reported comment summary if applicable
  let reportedCommentSummary: IDiscussionBoardComment.ISummary | null = null;
  if (created.reportedComment) {
    const comment = created.reportedComment;
    reportedCommentSummary = {
      id: comment.id,
      content: comment.content,
      author_type: comment.author_type,
      memberAuthor: comment.memberAuthor
        ? {
            id: comment.memberAuthor.id,
            username: comment.memberAuthor.username,
            display_name: comment.memberAuthor.display_name ?? null,
            profile_picture_url:
              comment.memberAuthor.profile_picture_url ?? null,
          }
        : null,
      moderatorAuthor: comment.moderatorAuthor
        ? {
            id: comment.moderatorAuthor.id,
            username: comment.moderatorAuthor.username,
            display_name: comment.moderatorAuthor.display_name,
            profile_picture_url: comment.moderatorAuthor.profile_picture_url,
            email_verified: comment.moderatorAuthor.email_verified,
            status: comment.moderatorAuthor.status,
            moderation_permissions:
              comment.moderatorAuthor.moderation_permissions,
            profile_visibility: comment.moderatorAuthor.profile_visibility,
            activity_visibility: comment.moderatorAuthor.activity_visibility,
            bio: comment.moderatorAuthor.bio ?? null,
            location: comment.moderatorAuthor.location ?? null,
            website_url: comment.moderatorAuthor.website_url ?? null,
            last_login_at: comment.moderatorAuthor.last_login_at
              ? toISOStringSafe(comment.moderatorAuthor.last_login_at)
              : null,
            created_at: toISOStringSafe(comment.moderatorAuthor.created_at),
            updated_at: toISOStringSafe(comment.moderatorAuthor.updated_at),
            deleted_at: comment.moderatorAuthor.deleted_at
              ? toISOStringSafe(comment.moderatorAuthor.deleted_at)
              : null,
          }
        : null,
      created_at: toISOStringSafe(comment.created_at),
      updated_at: toISOStringSafe(comment.updated_at),
    };
  }

  // Return complete report entity using the prepared timestamp
  return {
    id: created.id,
    discussion_board_member_id: created.discussion_board_member_id,
    reported_article_id: created.reported_article_id,
    reported_comment_id: created.reported_comment_id,
    reviewing_moderator_id: created.reviewing_moderator_id,
    report_reason: created.report_reason,
    report_details: created.report_details,
    status: created.status,
    resolution_notes: created.resolution_notes,
    reporter: reporterSummary,
    reportedArticle: reportedArticleSummary,
    reportedComment: reportedCommentSummary,
    reviewingModerator: null,
    created_at: now,
    updated_at: now,
    deleted_at: null,
  };
}

import { HttpException } from "@nestjs/common";
