    if (body.status === "active") {
      where.expires_at = { gt: now };
      where.lifted_at = null;
    } else if (body.status === "expired") {
      where.expires_at = { lte: now };
      where.lifted_at = null;
    } else if (body.status === "lifted") {
      where.lifted_at = { not: null };
