              ? toISOStringSafe(suspension.liftingModerator.deleted_at)
              : null,
          }
        : undefined,
    };
  });

  const pages = Math.ceil(total / limit);

  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: pages,
    },
    data,
  };
}

